window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["25885174"]={"book":{"id":25885174,"title":"积极达成","author":"王明伟","translator":"","publisher":"机械工业出版社","pubdate":"2014-5","isbn":"9787111464693","tags":["自我管理","情绪","管理","情绪管理","心理学","心理","积极","方法论"],"memCount":15},"np":1,"pb":[15],"idx":[{"i":7437,"t":"江畔月过1-2","l":"TF1-2","c":"江畔月","g":1,"p":1},{"i":7337,"t":"处理情绪的4A模型","l":"TF1-1","c":"江畔月","g":1,"p":1},{"i":7315,"t":"用PRO模型学会先处理情绪，后处理问题","l":"TF1-1","c":"江畔月","g":1,"p":1},{"i":7215,"t":"对抗消极情绪","l":"TF2-4","c":"深寒","g":1,"p":1},{"i":6499,"t":"理性识别消极情绪","l":"TF2-1","c":"深寒","g":1,"p":1},{"i":5429,"t":"利用4A模型处理情绪","l":"TF1-1","c":"江畔月","g":1,"p":1},{"i":5425,"t":"用PRO模型解决问题","l":"TF1-1","c":"江畔月","g":1,"p":1},{"i":3284,"t":"缓和情绪两步法","l":"TF1-1","c":"光东","g":1,"p":1},{"i":1725,"t":"面对棘手的问题时，掌握影响他人的方法，积极解决问题。","l":"TF2-3","c":"小鹿","g":1,"p":1},{"i":1724,"t":"分析坏情绪，积极调节3","l":"TF2-4","c":"小鹿","g":1,"p":1},{"i":1657,"t":"分析坏情绪，积极调节2","l":"TF2-4","c":"小鹿","g":1,"p":1},{"i":1656,"t":"分析坏情绪，积极调节","l":"TF2-4","c":"小鹿","g":1,"p":1},{"i":1451,"t":"如何迅速解决问题","l":"TF2-1","c":"朱莹","g":0,"p":1},{"i":1444,"t":"执行工作的时候，分工和跟进的wwwt工具","l":"TF2-2","c":"朱莹","g":0,"p":1},{"i":1140,"t":"通过调节认知来调节情绪","l":"TF1-1","c":"小鹿","g":0,"p":1}],"ms":[{"id":7437,"topic":"江畔月过1-2","learn_goal":"过级TF1-2","remark":"阐述积极调整情绪的方法和积极处理问题的方法，并提供简单易用的实用模型工具，以及贴近生活的具体应用案例。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"江畔月","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"大家好，我是江畔月，来自石家庄梧桐分舵，我个人的3个标签是产品经理、阅读、写作。我今天分享的片段来自《积极达成》——处理情绪的4A模型。今天挑战的是1-2的过级，现场还有 3 位小伙伴，分为一组，组长为Mona。 \r\n《积极达成》重点阐述了“积极调整情绪”和“积极处理问题”的方法，并提供给我们丰富易用的模型工具以及贴近生活的具体应用案例。\r\n当今社会的要求是“快与变”，我们要想适应甚至超越这种苛刻的要求，最基本的条件就是把事情做好，把面对的问题解决好，让结果“积极达成”。\r\n那么如何建立积极的情绪，防止陷入消极的情绪呢？我们需要持续不断的用耳、用眼、用脑去“倾听”更多客观的方面，以及用心的与对方保持良好的关系，学会换位思考。这就需要用到我们今天分享的拆解片段——处理情绪的4A模型。\r\n（所选图书为实用类）","ratings_count":1,"texts":[{"id":10898,"quote":"\u003cp>《积极达成》处理情绪的4A模型\u003c/p>\u003cp>1.&nbsp;\u003cstrong>Aware识别情绪：\u003c/strong>\u003c/p>\u003cp>识别情绪是处理情绪的第一步，如果我们都没有识别出情绪，就谈不上处理情绪。\u003c/p>\u003cp>\u003cstrong>2.Accept接受情绪：\u003c/strong>接受情绪是疏导情绪，而不是压制或对抗，只有我们接受了自己和他人的情绪，才有可能更加灵活的方式来处理情绪，就像打太极一样，硬碰硬，往往两败俱伤，先接受，然后进行化解才是最高的招式。\u003c/p>\u003cp>\u003cstrong>3.Analyze分析情绪：\u003c/strong>分析情绪的关键在于搞清楚情绪的来源，以及什么样的认知导致了我们这样的情绪，只有搞清楚认知，我们才能更好的调整情绪。\u003c/p>\u003cp>\u003cstrong>4.Adjust调整情绪：\u003c/strong>调整情绪的关键在于将导致消极情绪的消极认知调整为积极的认知，从而把消极的情绪调整为积极的情绪。\u003c/p>\u003cp>（所选拆页有具备可行动性，且有一定复杂性）\u003c/p>","explains":"\u003cp>人们在有消极情绪，特别是愤怒、焦虑等的情况之下，很难想出好的办法来解决问题，大家可能都有过这样的经历，当明显感到自己处于消极情绪中时，无法让自己集中精力专注地去思考该如何解决一个复杂的问题。另一方面，对问题有了明确的方法，如果带着消极情绪去做，也很难把这个问题处理好。\u003c/p>\u003cp>当意识到我们有消极情绪出现的时候，可以用4A模型分析梳理情绪。\u003c/p>\u003cp>\u003cstrong>处理情绪的步骤\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>识别情绪\u003c/strong>：识别自己或他人现在处在什么样的消极情绪之中\u003c/p>\u003cp>2.&nbsp;\u003cstrong>接受情绪\u003c/strong>：先接受自己或他人的情绪，然后再想办法化解。\u003c/p>\u003cp>3.&nbsp;\u003cstrong>分析情绪\u003c/strong>：搞清楚情绪来源，何种认知导致消极情绪的发生\u003c/p>\u003cp>4.&nbsp;\u003cstrong>调整情绪\u003c/strong>：将导致消极情绪的认知调整为积极的认知，如何转变呢？在这里和大家分享一个小方法，就是将“为什么”换成“如何或怎样”，举个例子，“为什么领导老是针对我呢？”转为“我如何做，才能提交让领导满意的工作呢？”通过小的变化，是不是将消极情绪引到了解决问题上了。\u003c/p>\u003cp>\u003cstrong>案例分享：\u003c/strong>\u003c/p>\u003cp>我的朋友小A和男友最近又陷入冷战。男友已经两天没有联系她。为此她很苦恼，但又不想主动联系男友妥协，问我该怎么办。\u003c/p>\u003cp>我用4A模型帮她进行了分析，她的调整步骤如下：\u003c/p>\u003cp>l&nbsp;\u003cstrong>识别情绪\u003c/strong>：问自己“我现在有什么样的情绪？”答案是焦虑，不安，猜忌。\u003c/p>\u003cp>l&nbsp;\u003cstrong>接受情绪\u003c/strong>：我接受自己的情绪，我要想办法化解矛盾。\u003c/p>\u003cp>l&nbsp;\u003cstrong>分析情绪\u003c/strong>：什么原因导致我这种情绪发生呢？我的认知停留在“他应该为我考虑，要宠我，一切已我为中心”，这样的认知导致他没有联系我就会心里没底。\u003c/p>\u003cp>l&nbsp;\u003cstrong>调整情绪\u003c/strong>：我要调整自己的认知，就需要将“为什么他不主动联系我？”调整到“我如何做，才能让两个人的关系步入正轨”，首先的行动就是主动沟通，化解不愉快。\u003c/p>\u003cp>几天之后她打电话给我，说和男友和好了，原因是男友出差，怕电话解释不清，就想出差回来后好好解释，没有想到她会主动联系自己，误会解开，双方重归于好。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>\u003c/p>\u003cp>通过处理情绪的4A模型，可以更好地调节消极情绪，达成积极的结果，让你更好地解决问题。\u003c/p>\u003cp>（简要提炼原文及行动建议，并用一个实例分析用法）\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>\u003c/p>\u003cp>通过读这个拆页和案例分享，我们了解到先调整情绪，后处理问题的重要性。那么，请花2分钟回忆一下有没有过使用4A模型的经历呢，有哪次是因为使用4A模型让关系或谈话好转，也或许是没有使用4A模型让关系或谈话陷入不快或僵局。\u003c/p>\u003cp>总之就是你是如何将消极的情绪转为积极，进而集中精力解决问题的？大家可以先在小组内分享，每人一分钟，分享完毕后，我们选一个人分享，总时间8分钟。\u003c/p>\u003cp>（发出指令，让学习者小组内分享相关经验）\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>建超分享：\u003c/strong>\u003c/p>\u003cp>上周出差遇到报销的问题，需要开住宿发票，与单位内勤沟通是有些不愉快，但通过及时调整，处理好了此问题。\u003c/p>\u003cp>\u003cstrong>识别情绪：\u003c/strong>当时比较无语、愤怒，在同行的人面前很尴尬。\u003c/p>\u003cp>\u003cstrong>接受情绪：\u003c/strong>意识到自己处在消极情绪之中，通过336呼吸法让自己先冷静，稳定情绪后将注意力集中到如何处理问题上来。\u003c/p>\u003cp>\u003cstrong>分析情绪：\u003c/strong>1、自己出发前没有考虑周全，事先询问；2、内勤分内的事情，没有提前告知我。我“内勤应该此事比我清楚，应该提前告知”的认知让我将消极情绪释放出来。\u003c/p>\u003cp>\u003cstrong>调整情绪：\u003c/strong>通过呼吸调节让自己稳定后，我询问同行的人“你们如何解决此问题？”果然迅速得到反馈，顺利解决问题。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>\u003c/p>\u003cp>大家分享的案例很精彩，相信大家已经掌握了4A模型，那么，你计划在未来一周如何将它运用起来呢？请写下具体的场景及执行计划，让我们更好的应对消极情绪！要有可衡量和观测的后果。\u003c/p>\u003cp>（发出指令，让学习者小组写下自己的A2）\u003c/p>\u003cp>（时间关系，未有小伙伴现场分享）\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Mona分享：\u003c/strong>\u003c/p>\u003cp>预计周二早上，大区经理会追问我数据是否真实的问题，因为本周已经有些苗头了。\u003c/p>\u003cp>\u003cstrong>识别情绪：\u003c/strong>如果领导对我有质疑，我肯定本能是反抗，据理力争。面对强势的领导，难免会败下来，所以情绪会陷入消极，脸色也会不好看，沮丧。\u003c/p>\u003cp>\u003cstrong>接受情绪：\u003c/strong>我毕竟是个新手，领导严格要求，也是对我的培养，就是现阶段有点不理解，难接受。\u003c/p>\u003cp>\u003cstrong>分析情绪：\u003c/strong>1、确实没有做好数据；2、领导是一个注重细节的人。我的认知停留在“为什么他总是难为人”才导致了我的消极情绪，这使我意识到，不痛快对工作没有任何好处。\u003c/p>\u003cp>\u003cstrong>调整情绪：\u003c/strong>先看个笑话忘掉不愉快！然后问自己“如何才能做好数据？”向了解此工作的同事请教，追求数据可靠性。努力把事情做好。\u003c/p>\u003cp>大家都写完A2了，希望大家可以把你的计划很好地落实下去，希望我今天的分享能有助于提高你对消极情绪的管理，今天分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1552917707000,"updated_at":1552917707000,"ria":true},{"id":7337,"topic":"处理情绪的4A模型","learn_goal":"学会先处理情绪，再处理问题，让结果积极达成","remark":"先处理情绪，才能专注的思考，然后把事情做好。影响他人不仅要克己服人还要互惠共赢。策略是合作利他，而非自私对抗。","level":"TF1-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"江畔月","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是江畔月，来自石家庄梧桐分舵。我今天分享的片段来自《积极达成》——处理情绪的4A模型。今天挑战的是1-2的过级，现场还有4位小伙伴，2人一组。&nbsp;\u003c/p>\u003cp>《积极达成》重点阐述了“积极调整情绪”和“积极处理问题”的方法，并提供给我们丰富易用的模型工具以及贴近生活的具体应用案例。\r\n当今社会的要求是“快与变”，我们要想适应甚至超越这种苛刻的要求，最基本的条件就是把事情做好，把面对的问题解决好，让结果“积极达成”。\r\n那么如何建立积极的情绪，防止陷入消极的情绪呢？我们需要持续不断的用耳、用眼、用脑去“倾听”更多客观的方面，以及用心的与对方保持良好的关系，学会换位思考。这就需要用到我们今天分享的拆解片段——处理情绪的4A模型。\r\n（所选图书为实用类）\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10782,"quote":"\u003cp>《积极达成》处理情绪的4A模型\u003c/p>\u003cp>1.&nbsp;\u003cstrong>Aware识别情绪：\u003c/strong>\u003c/p>\u003cp>识别情绪是处理情绪的第一步，如果我们都没有识别出情绪，就谈不上处理情绪。\u003c/p>\u003cp>\u003cstrong>2.Accept接受情绪：\u003c/strong>接受情绪是疏导情绪，而不是压制或对抗，只有我们接受了自己和他人的情绪，才有可能更加灵活的方式来处理情绪，就像打太极一样，硬碰硬，往往两败俱伤，先接受，然后进行化解才是最高的招式。\u003c/p>\u003cp>\u003cstrong>3.Analyze分析情绪：\u003c/strong>分析情绪的关键在于搞清楚情绪的来源，以及什么样的认知导致了我们这样的情绪，只有搞清楚认知，我们才能更好的调整情绪。\u003c/p>\u003cp>\u003cstrong>4.Adjust调整情绪：\u003c/strong>调整情绪的关键在于将导致消极情绪的消极认知调整为积极的认知，从而把消极的情绪调整为积极的情绪。\u003c/p>\u003cp>（所选拆页有具备可行动性，且有一定复杂性）\u003c/p>","explains":"\u003cp>人们在有消极情绪，特别是愤怒、焦虑等的情况之下，很难想出好的办法来解决问题，大家可能都有过这样的经历，当明显感到自己处于消极情绪中时，无法让自己集中精力专注地去思考该如何解决一个复杂的问题。另一方面，对问题有了明确的方法，如果带着消极情绪去做，也很难把这个问题处理好。\u003c/p>\u003cp>当意识到我们有消极情绪出现的时候，可以用4A模型分析梳理情绪。\u003c/p>\u003cp>\u003cstrong>处理情绪的步骤\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>识别情绪\u003c/strong>：深呼吸，问自己“我现在有什么样的情绪”\u003c/p>\u003cp>2.&nbsp;\u003cstrong>接受情绪\u003c/strong>：我接受我现在的情绪，遇到什么样事情有什么样的情绪是正常的。\u003c/p>\u003cp>3.&nbsp;\u003cstrong>分析情绪\u003c/strong>：在什么情况下，我的情绪是什么，所以情绪产生\u003c/p>\u003cp>4.&nbsp;\u003cstrong>调整情绪\u003c/strong>：我因为有什么样的认知，导致我如何，所以我不陷入消极情绪，我要如何，所以我要做怎么做，通过目标和行动引导将情绪调整为积极。\u003c/p>\u003cp>我的同事小李和男友最近又陷入冷战。男友已经两天没有联系她。她很苦恼，但又不想主动联系男友妥协，问我该怎么办。\u003c/p>\u003cp>我用4A模型帮她进行了分析，她的调整步骤如下：\u003c/p>\u003cp>l&nbsp;\u003cstrong>识别情绪\u003c/strong>：深呼吸，问自己“我现在有什么样的情绪？”\u003c/p>\u003cp>l&nbsp;\u003cstrong>接受情绪\u003c/strong>：我接受我现在的情绪，遇到冷战时他不联系我，我生气是正常的。\u003c/p>\u003cp>l&nbsp;\u003cstrong>分析情绪\u003c/strong>：在“我想即使我做错了，作为男人，你都应该心胸大些，包容我，应该先打电话给我道歉”的认知下，我才特别生气。\u003c/p>\u003cp>l&nbsp;\u003cstrong>调整情绪\u003c/strong>：我因为有男友必须先妥协道歉的认知，导致我“专横无理的应该”，所以我不陷入责备的漩涡之中，我要试着换位思考，先了解他有什么原因，再做进一步决定”\u003c/p>\u003cp>几天之后她打电话给我，说和男友和好了，原因是男友出差，怕电话解释不清，就想出差回来后好好解释，没有想到她会主动联系自己，误会解开，双方重归于好。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>\u003c/p>\u003cp>通过处理情绪的4A模型，可以更好地调节消极情绪，达成积极结果。\u003c/p>\u003cp>（简要提炼原文及行动建议，并用一个实例分析用法）\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>通过读这个拆页和案例分享，我们了解到先调整情绪，后处理问题的重要性。那么，请花2分钟回忆一下有没有过不自觉使用4A模型的实例呢，大家可以先在小组内分享，每人一分钟，分享完毕后，每组选一个人分享，总时间8分钟。\u003c/p>\u003cp>（发出指令，让学习者小组内分享相关经验）\u003c/p>\u003cp>\u003cstrong>Mona分享案例：\u003c/strong>\u003c/p>\u003cp>前几天去某公司面试，面试官给出的待遇和承诺让我很高兴，有点飘飘然，但感到自己明显的过度兴奋了。\u003c/p>\u003cp>识别情绪：对未来的憧憬过于兴奋，需要回归理性。\u003c/p>\u003cp>接受情绪：别人对我能力的认可，让我很开心，但我需要冷静下来认真思考利弊。\u003c/p>\u003cp>分析情绪：我为什么会处在这种亢奋之中？可能是别人给我画的饼充满诱惑，但其实这不是客观事实，想达到那个薪资待遇需要付出很多，与现有能力不匹配。\u003c/p>\u003cp>调整情绪：让自己冷静下来，多问自己几个为什么，从多个角度思考这件事情是否是自己期望过高。让情绪平静下来后思考问题。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>大家分享的案例很精彩，相信大家已经掌握了4A模型，那么，你计划在未来一周如何将它运用起来呢？请写下具体的场景及执行计划，让我们更好的应对消极情绪！要有可衡量和观测的后果。\u003c/p>\u003cp>（发出指令，让学习者小组写下自己的A2）\u003c/p>\u003cp>因时间关系，现场未有小伙伴分享A2。\u003c/p>\u003cp>补充：文羊分享：\u003c/p>\u003cp>经常和爱人因为孩子作业问题闹矛盾，从而产生不好的情绪。如果今天回家，遇到爱人发脾气，可以尝试用4A模型来梳理自己的情绪。\u003c/p>\u003cp>识别情绪：老婆不高兴是因为孩子，而不是因为我做错什么。\u003c/p>\u003cp>接受情绪：她的情绪一会就过，不用太担心。哄哄就会好了。\u003c/p>\u003cp>分析情绪：老婆之所以生气，是因为孩子的作业，我可以多关心孩子，替她分担一些孩子教育问题，让她少生气。\u003c/p>\u003cp>调整情绪：老婆不高兴，我就不能再发脾气了，我要做灭火器，让老婆消气，家里的气氛才能温馨。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>大家应该都写完A2了，希望大家可以把它很好地落实下去，希望我今天的分享能有助于提高你对消极情绪的管理，今天分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1551797763000,"updated_at":1551798850000,"ria":true},{"id":7315,"topic":"用PRO模型学会先处理情绪，后处理问题","learn_goal":"扭转消极局面，达成积极结果","remark":"积极达成这本书，在人与人交往中实用比较多，处理情绪，处理负面思想，使自己能够保持一颗良好的心态去面对生活中的烦恼，极其重要，每时每刻保持一颗愉悦的心理状态，是高效率工作、高品质生活的前提。","level":"TF1-1","duration":90,"status":30,"type":0,"chaishujia":{"username":"江畔月","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>大家好，我是江畔月，我的三个标签是产品经理、80后、终身学习。我现在从事软件产品经理的工作，主要是分析用户需求，与开发打交道，写各种文档。业余时间是阅读和写作，不过都在初期，需要走的路还很远。相比各位小伙伴，我年龄稍长，但学习是不分年龄的，什么时候开始都不晚，不是吗？做一名终身学习者是我的目标和追求！\u003c/p>\u003cp>走进拆书帮，也是为了更高效的学习，教是为了更好的学，所以我又走在拆书家的进阶之路。和热爱学习的小伙伴们一起成长，因为，一个人虽走的快，但一群人才能走的远。\u003c/p>\u003cp>可能大家第一次听到拆书这个词，\u003cstrong>“拆书”\u003c/strong>是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调\u003cstrong>以学习者为中心\u003c/strong>，而不是以知识为中心，要把知识关联学习者的经验，规划具体的运用。\u003c/p>\u003cp>分为个人学习的拆书法，和组织学习的拆书法：个人学习的应用是\u003cstrong>便签法\u003c/strong>，让人读一本书，就能达到参加同主题营培训的效果；组织学习的应用是一位拆书家拿一本书，加工出一场现场学习，\u003cstrong>引导和促进一群人把知识拆为己用\u003c/strong>。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>\u003cstrong>“拆书帮”\u003c/strong>是基于拆书法的学习爱好者社群，他们在一起吸收书给予的能力，成长蜕变，然后一起释放学习促进者的能量。他们分享，传播，给予，付出。\u003c/p>\u003cp>拆书帮落地形式表现为各地的拆书帮分舵。拆书帮分舵是非盈利性的学习爱好者俱乐部，爱好者们一起锻炼把知识转化为自身能力的能力。分舵的使命是帮助更多学习爱好者成长为拆书家，源源不断的壮大拆书家的队伍。\u003c/p>","ratings_count":1,"texts":[{"id":10753,"quote":"\u003cp>我们今天的拆书片段来自《积极达成》P136\u003c/p>\u003cp>主题:用PRO模型解决问题\u003c/p>\u003cp>要想解决好问题，我们必须弄清楚三个关键问题：\u003c/p>\u003cp>1.想清楚“问题是什么”。只有定位清楚问题是什么，才能为下一步解决问题打好基础。如果我们连要解决什么问题都不清楚或者搞错了，解决问题就更加不可能了。\u003c/p>\u003cp>2.搞清楚“原因是什么”，问题往往是一个结果，背后往往有导致问题产生的原因，所以我们要定位到导致问题的原因，才能很好的解决问题。\u003c/p>\u003cp>3.找清楚“对策是什么”。我们在分析清楚导致问题的原因之后，要对症下药的找到决策，才能解决问题。\u003c/p>\u003cp>根据三个步骤总结为解决问题的PRO工具:\u003c/p>\u003cp>第一步，Problem clarification澄清问题，想清楚“问题是什么”？\u003c/p>\u003cp>第二步，Reasons analysis分析原因，搞清楚“原因是什么”？\u003c/p>\u003cp>第三步，Options selection选定方案，找清楚“方案是什么”？\u003c/p>","explains":"\u003cp>想想看，我们身边是不是有这两类人：一类人是处理问题的小能手，这样的人工作高效有条理，还把生活打造的多姿多彩，有滋有味。另一类人就是每天忙忙碌碌，也不见他休息偷懒，但却工作生活一团糟，只是在辛苦忙碌，看不到结果。有一句话叫“结果会告诉你答案”。那结果告诉我们什么答案呢？因为什么导致这两类人存在如此大的差异呢？首先带大家来认识——\u003c/p>\u003cp>\u003cstrong>1.什么是问题？\u003c/strong>\u003c/p>\u003cp>处理事情主要是解决问题。要想解决好面对的问题，首先要搞清楚，什么是问题？\u003c/p>\u003cp>问题就是目标和现状的差距。解决问题实际上就是设定目标，发现现状与目标之间的差距。为减少这些特定的差距，寻找记忆中存在或者经过的探索，而形成适当或者是适用的工具的过程。\u003c/p>\u003cp>2.\u003cstrong>总结I\u003c/strong>\u003c/p>\u003cp>\u003cstrong>What:\u003c/strong>用PRO模型解决问题，找到解决问题之前需确定的三个关键问题。\u003c/p>\u003cp>\u003cstrong>Why:\u003c/strong>这个方法可以帮助我们更好的定位问题，以及定位造成问题的原因，对症下药，找到解决方法。如果不用这个方法，我们可能不知道问题是什么，即便搞清楚问题了，也要拿出切实可行的对策，否则，就不能从根本上解决问题。\u003c/p>\u003cp>\u003cstrong>Where:\u003c/strong>无论是自己的问题，还是与他人合作时产生的矛盾，当我们面对问题想更好解决时，都可以尝试此方法。\u003c/p>\u003cp>\u003cstrong>How:\u003c/strong>具体实施步骤是：\u003c/p>\u003cp>第一步，澄清问题，想清楚问题是什么？\u003c/p>\u003cp>第二步，分析原因，搞清楚原因是什么？\u003c/p>\u003cp>第三步，选定方案，找清楚方案是什么？\u003c/p>","interaction":"\u003cp>我一直想健身，可是就是没有行动。随着工作学习任务多，更没有时间锻炼，所以日子在拖延中度过。今年3月份，我的背痛的厉害，让我不得不重新重视锻炼这个问题，想想自己已经半年多没有踏进健身房的门了，真的每天就抽不出半小时锻炼吗？为了督促我锻炼，我还加入了一个健身打卡群，打卡失败押金蒸发那种，有了押金激励我动力很足，想努力拿回自己的钱，可是我还因为一次朋友聚会没有完成打卡。\u003c/p>\u003cp>此事就让我感到特别焦虑，觉得我这么小的事情怎么都坚持不了21天呢？\u003c/p>\u003cp>后来我偶然的机会看到了PRO模型，通过它的引导，我一步步认清我存在的问题，并有了明确的解决方案。\u003c/p>\u003cp>1.澄清问题：日子忙碌，精力不够用，如何在工作之余锻炼身体？\u003c/p>\u003cp>2.分析原因：没有锻炼的习惯，工作忙碌，只能利用碎片化时间行动，可就是没有行动，缺乏动力，经常犯懒，拖延。归根到底还是没有明确的，具体的行动方案，我的努力只停留在口号层级“我要健身，我要锻炼”。\u003c/p>\u003cp>3.选定方案：\u003c/p>\u003cp>l&nbsp;睡前平板支撑三次，每次最少1分钟\u003c/p>\u003cp>l&nbsp;每周两次健身房运动，每次一小时瑜伽\u003c/p>\u003cp>l&nbsp;出行三公里内尽量骑车。晚饭后带孩子下楼溜圈，20分钟左右。\u003c/p>\u003cp>通过这样的调整，我现在每天也可以有30分钟的锻炼时间了，周末可以有1小时，通过PRO模型的引导，真的解决了我没有时间健身的问题，而且轻轻松送地坚持了一个多月，身体状况好多了。\u003c/p>\u003cp>有了成功经验以后呢，我就想我是不是可以把它应用在解决我工作低效的问题。&nbsp;我有早计划晚复盘的习惯，可是晚上复盘是总是存在没有完成的任务，一开始焦虑，后来竟习以为常了！有人说，你干嘛这么累，少定点任务不就行了？可我不想减，有压力才有动力啊！\u003c/p>\u003cp>我给自己制定了高效完成一天工作的目标，执行时间就是明天，为此，我需要用PRO模型来梳理我的问题。\u003c/p>\u003cp>1.&nbsp;澄清问题：如何高效完成明天工作计划？\u003c/p>\u003cp>2.&nbsp;分析原因：\u003c/p>\u003cp>以前工作低效的原因是什么呢？频繁被外界打扰，被手机干扰、无法集中精力进行深度工作。工作计划也经常被临时性任务打乱，还有碎片化时间利用不充分。\u003c/p>\u003cp>3.行动方案\u003c/p>\u003cp>l&nbsp;列清单，将明天所做的事情列表，标注优先级，给任务加截止时间。临时性任务梳理优先级之后排序处理。\u003c/p>\u003cp>l&nbsp;减少外界干扰。工作时将手机静音，不登录电脑微信，不浏览新闻。利用休息时间，批量处理回复，不重要群里的消息不点开看，不要脑残的只想着消灭小红点。做到只在晚上睡前浏览一次朋友圈，10分钟以内。\u003c/p>\u003cp>l&nbsp;用碎片时间完成小任务（思考、读书笔记打卡）。\u003c/p>\u003cp>明天一早把行动方案贴在办公桌旁，督促自己执行，希望明天晚上复盘的时候，我可以骄傲的说，我做到了今日事，今日毕。\u003c/p>\u003cp>今天的分享到此结束，希望大家对拆书帮有所了解，对PRO模型有所尝试，谢谢各位的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1551625519000,"updated_at":1551850000000,"ria":true},{"id":7215,"topic":"对抗消极情绪","learn_goal":"学会使用CCEA模型四个步骤，察觉并对抗消极情绪","remark":"本书认为在分析和解决问题的时候，应当先处理情绪，再处理问题，并提出了处理情绪的4A模型和处理问题的PRO模型，帮助我们高效和谐地解决问题。本次拆书着重于处理消极情绪，借用CCEA的四个步骤，帮助我们察觉情绪，结合具体的事件场景，分析出情绪背后的认知，进而对抗消极情绪。","level":"TF2-4","duration":55,"status":29,"type":0,"chaishujia":{"username":"深寒","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;各位伙伴下午好！ 首先请大家按照座位顺序依次两两组成一组。今天分享的主题是对抗消极情绪，那我们看看哪些是消极情绪呢？比如愤怒、忧伤、沮丧、疲惫。\r\n这些情绪会给我们带来什么呢？我们会因为愤怒而与他人产生冲突，影响人际关系；会因为烦躁而不能准时完成工作；会因为过度紧张而忘掉重要的工作内容。\r\n可见，消极情绪往往带给我们的都是不好的影响，所以我们要尽可能避免。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; \u003cstrong>【学习目标】\u003c/strong>因此，今天的第一个学习目标就是：学会CCEA模型的四个步骤，能够从自己的行动开始察觉消极情绪，结合具体的事件场景，分析出情绪背后的认知，进而对抗消极情绪。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp;图书介绍：\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 【F】\u003c/strong>《积极达成：处理好情绪再处理问题》这边书的作者是王明伟，是美国知名影响力与领导力培训机构Vital Smarts公司在大陆地区认证最早和授课最多的专职讲师之一。本书认为在分析和解决问题的时候，我们需要先处理情绪，再处理问题。并且有针对性地提出了处理情绪的4A模型，和处理问题的PRO模型，帮助我们高效和谐解决问题。\u003c/p>\u003cp>\u003cstrong>&nbsp; 【A】\u003c/strong>相比于同类型的影响力书籍，这本书不是一本理论书，而是一本工具书，结构清晰，逻辑严密，案例丰富，而且最特别的就是，作者是中国人，所以在文字表述上面更贴近我们的文化习惯，读起来更容易理解。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 【B1】\u003c/strong>这本书对我们有什么用呢？现在我们工作和学习的大环境是追求快速适应变化，然而现实生活中我们工作进展缓慢，个人情绪低落，人际关系紧张，我们想要改善，但又时常力不从心，不知道从哪里下手。这本书就告诉了我们一个可行的流程：先处理情绪，避免陷入消极情绪，然后再按照科学的思路和方法分析解决事情。帮助我们把事做好，把人际关系处理好。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;\u003cstrong>【B2】\u003c/strong>而今天学习的两个片段则是介绍一个很实用的工具——CCEA模型，来帮助我们察觉自身的消极情绪，了解引起这种情绪的事件原因，分析并调整相应的行动，从根本上改变或减少消极情绪。\u003c/p>\u003cp>接下来，请大家用2分钟的时间阅读拆页原文。阅读完的伙伴请举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":10624,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; Condintion(具体的情景）＞Cognition（产生对于该情景的认知）＞Emotion（引起了情绪）＞Action（根据情绪做出的相应行动）\u003c/p>\u003cp>&nbsp;&nbsp;利用一个家庭生活中的例子来理解一下CCEA模型：你家儿子8岁了，刚上小学二年级。从上学开始语文成绩一直不是很好，而且还特别贪玩，尤其喜欢看电视，所以你为了让他的成绩尽快赶上来，要求他只能晚上8点半至9点看半小时电视，他也答应了。你工作的地方离家比较远，所以你一般到家就7点多了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;今天下午你从公司外出办事，办完事就直接回回家了，到家时刚刚6点。你一推门进家，就发现你儿子在看电视（具体的情景），这时你心里想：“这孩子太贪玩了，今天要不是我回来得早，我还发现不了！”（你对于当前情况的认知）。基于这样的想法，你非常生气，火网上撞（你产生了情绪）。你开始责备孩子，说他不诚实，不听话，可能还会惩罚他（这些都是你采取的行动）。我想类似的例子，大家还能举出不少。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;情绪源于认知，这条原理对于分析和调整情绪至关重要。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>【why】\u003c/strong>大家可能发现，当生气、焦虑、愤怒、忧伤等消极情绪来临的时候，我们几乎是察觉不到的，事后即便反应过来了，好像也没什么用，下一次还是会被情绪影响。头疼的问题始终没有解决，为什么呢？原因就是我们孤立地看待情绪，没有对情绪背后的事件原因进行归纳，没有认识到或许是自己的认知错误导致了现在的消极情绪，于是才让自己的行为一次次偏离正确的轨道。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; \u003cstrong>【what】\u003c/strong>对此，片段中作者就给出了我们一个CCEA模型，帮助我们察觉、分析情绪背后的认知问题：\u003cstrong>C（情景）-C（认知）-E（情绪）-A（行动）\u003c/strong>。通过理性地将情绪与对应的事件情景、认知以及行动串起来，使我们不再孤立地看待情绪，改变认知才能改变情绪。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>【how】\u003c/strong>怎样运用CCEA模型来分析消极情绪及背后的认知呢？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>第一步，察觉情绪。\u003c/strong>通过身体的表现来察觉情绪，例如手心出汗是紧张，攥紧拳头是生气。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>第二步，回忆场景。\u003c/strong>回忆最近一次发生这种情绪的时间，时间、人物、地点，发生了什么。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>第三步，回忆行动。\u003c/strong>回忆这种场景下自己采取了哪些行动，想想这些行动是不是自己不想要的？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>第四步，分析认知。\u003c/strong>为什么会有这样的情绪？回忆下你当时的内心独白，或者能更深一步，找出自己哪一方面的需求没有被满足。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>【案例】\u003c/strong>下面我就举一个自己的例子：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我发现我最近总是生气，生气的时候我会不舒服，会胃疼，我要对抗这种消极情绪，于是我开始运用以上四个步骤：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;首先是察觉情绪，我发现我生气的时候总是攥紧拳头，那么下次我就知道我攥紧拳头可能就是我生气了；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第二步，回忆最近一次生气的场景，就在昨天，我跟我妈妈通电话，没说两句她就又开始说“你快点找个人嫁了吧！”；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第三步，回忆行动，当时听到这句话的时候我一下子就炸了，二话不说就挂了我妈的电话，当然这不是我想要的，因为她会伤心；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第四步，分析认知，为什么我会在妈妈每次催婚的时候就生气呢？我认真想了想，其实是我感觉到被控制，我认为妈妈不考虑我的感受，想用母亲的权威来控制我。而我内心渴望被满足的需求是：被母亲信任、被认可。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 【不那么做的坏处】\u003c/strong>&nbsp;如果我们没有运用CCEA模型来分析情绪背后的认知会怎么样呢？我们少了一样自我察觉的工具，就像少了一道通往幸福的大门，或许，我们会一直这样不自觉地被各种消极情绪牵着鼻子走，让消极情绪影响自己的工作生活人缘，美好人生的目标就这么离我们远去了。\u003c/p>","interaction":"\u003cul>\u003cli>\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003c/li>\u003c/ul>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>【显像提问】\u003c/strong>接下来我们一起来回忆，最近一周内自己有没有因为被消极情绪影响的经历？比如刚才说的生气，因为生气，我们感觉心里很不爽，但是不知道是什么让自己烦躁，一团乱麻。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;回忆下当时发生了什么？自己当时是怎么处理自己情绪的，是主动顺利地调整了，还是迟迟没有解决，又或者是不了了之？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>【反思加工经验】\u003c/strong>如果以后再遇到这样的情况，你会怎样运用这四个步骤分析出导致自己情绪的事件及背后的认知？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 接下来给大家每人1分钟的时间，跟你同组的伙伴分享一下你的A1经历。\u003c/p>\u003cp>\u003cstrong>学习者案例分享：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 有一次跟婆婆通话之后我就生气了，我很生气又不能对婆婆发作，就狠狠骂了我老公。这个事情我自己也莫名其妙的。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 用CCEA模型来看，我生气是因为自己之前一直被婆婆催着快点要小孩，现在怀上了，婆婆居然没有关心自己（周围的人都关心自己了）。尽管我也骂了我老公，但是心里仍然不平。虽然这件事就这么过去了，但通过今天的分析，我知道了我的内心是觉得我怀了宝宝了希望得到周围所有人的关怀，婆婆作为亲近的人，没有给自己关怀就会感觉委屈，下一次如果遇到这样的情况，我就会意识到是我的内心需求导致我生气的，就可以自己做调整。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":10625,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; \u003cstrong>【学习目标】\u003c/strong>第二个片段的学习目标是：通过四个步骤学会使用CCEA结构化日志，帮助我们从源头上了解自己的认知，进而调整消极情绪，并改变行为和结果。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 接下来请大家用3分钟的时间阅读片段二，阅读完的伙伴请举手示意我。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我们利用结构化日志的原理结合CCEA模型，拓展为CCEA结构化日志：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>前提（时间/地点/人物/事件）Condition\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003cp>Cognition\u003c/p>\u003c/td>\u003ctd>\u003cp>情绪\u003c/p>\u003cp>Emotion\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003cp>Action\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003cp>Result\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;CCEA结构化日志的作用在于发现哪些情景会对你的情绪产生影响，分析你为什么会产生情绪，帮助你从源头进行改善，从根本上调整你经常出现的消极情绪。所以，如果你想从根本上改善自己的情绪，CCEA结构化日志是非常有帮助的。\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp; 第一，分析“前提”的共性，找出让你出现过激情绪的共性前提。通过一段时间的结构化日志记录，你就会发现对于某种你特别想改善的情绪，很有可能是出现在一些有共性的前提下，比如：在某个人和你沟通时，你经常出现这样的情绪；或者某个事件出现时，你经常出现这样的情绪。找出共性的前提是非常重要的，因为你可以通过解决共性问题，使你在面对这些共性问题时有更加积极健康的情绪。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第二，基于共性前提，分析自己的认知。自己反思一下：为什么在这个共性前提下，我总是表现出这样的情绪？是什么样的认知影响了我？利用这个问题，深入分析自己的认知，你就可以发现那个操纵你情绪的幕后黑手了。往往当你挖出自己的认知时，会发现对于共性前提，自己的认知是非常绝对、偏激的，可能你自己都会觉得可笑，但这只幕后黑手已经捣蛋了很长时间了。最重要的一点，警惕这些偏激的认知，以后不要再用这些错误的认知来影响自己的情绪了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第三，化解偏激的认知，调整自己的情绪和行动。你可以重新调整自己的认知，把通过结构化日志分析出来的不正确、不健康的认知，调整为健康和积极的认知，这样就可以调整自己的情绪和行为。尤其是行为，对于之前过激的行为，你现在可以用一种新的行为来替代它。比如，当和某人在讨论问题有不同意见时，你总是很冲动地和他争吵，结果搞得双方无法来解决问题。为了避免这种争吵再次发生，当你情绪快要激动时，你可以提前设计一种新的行为来替代争吵，你可以告诉对方自己要去打杯水。通过这个新行为来避免双方的冲突，等你打水回来多半已经冷静下来，再谈事情往往会有更好的效果。下次你面对这种情况时，就可以用这种方法替代之前的不好行为，从而避免你们再次冲突。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; \u003cstrong>&nbsp;【what】\u003c/strong>CCEA结构化日志是基于前文我们看到的CCEA模型建立的，是一个工具，通过观察记录自己的情绪和事件，方便我们反思情绪背后的认知，然后通过改变认知来调整情绪和行动。同时也是建立起情绪管理习惯的方法之一。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>【细化行动步骤】\u003c/strong>怎样利用结构化日志来对抗消极情绪呢？\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;第一步，每日记录情绪、事件、行动、结果。\u003c/strong>事件当中需要记录时间、地点、人物和经过，这样方便下一步的总结。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 第二步，总结共性。\u003c/strong>这些事件都跟某个场景、某个人或某个物品有关。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 第三步，分析认知。\u003c/strong>根据这个共性，反思自己的内心独白是什么，这种认知是不是不正确的？是不是偏激的？\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 第四步，调整并实践。\u003c/strong>意识到自己的认知可能是不对的，我们对应地去写下正确的认知，然后尝试改变，调整情绪。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>情绪\u003c/td>\u003ctd>事件（时间/地点/人物/经过）\u003c/td>\u003ctd>共性\u003c/td>\u003ctd>行动\u003c/td>\u003ctd>认知\u003c/td>\u003ctd>结果\u003c/td>\u003c/tr>\u003ctr>\u003ctd>第1步\u003c/td>\u003ctd>第1步\u003c/td>\u003ctd>第2步\u003c/td>\u003ctd>第1步\u003c/td>\u003ctd>第3步、第4步\u003c/td>\u003ctd>第4步\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; \u003cstrong>【案例意译】\u003c/strong>我们以原文片段中的一个小例子来看，我今天生气了，事情是我与项目组的同事小毛在讨论问题时意见不合，总是会发生争吵，结果我们就没办法解决工作问题，项目进展缓慢。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;利用CCEA结构化日志我们怎么做？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 第一步：记录。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>事件\u003c/p>\u003cp>（时间/地点/人物/经过）\u003c/p>\u003c/td>\u003ctd>\u003cp>共性\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>生气\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>周五下午，办公室，小毛，装修方案意见不合。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>\u003cstrong>争吵\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>\u003cstrong>不欢而散，项目进度停滞。\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第二步，总结共性。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>事件\u003c/p>\u003cp>（时间/地点/人物/经过）\u003c/p>\u003c/td>\u003ctd>\u003cp>共性\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>生气\u003c/p>\u003c/td>\u003ctd>\u003cp>周五下午，办公室，小毛，装修方案意见不合。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>只要是跟小毛讨论问题，就经常会生气。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>争吵\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>不欢而散，项目进度停滞。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; 第三步，分析认知。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>事件\u003c/p>\u003cp>（时间/地点/人物/经过）\u003c/p>\u003c/td>\u003ctd>\u003cp>共性\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>生气\u003c/p>\u003c/td>\u003ctd>\u003cp>周五下午，办公室，小毛，装修方案意见不合。\u003c/p>\u003c/td>\u003ctd>\u003cp>只要是跟小毛讨论问题，就经常会生气。\u003c/p>\u003c/td>\u003ctd>\u003cp>争吵\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>我认为小毛是新人不专业，而自己希望能跟专业的人合作。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>不欢而散，项目进度停滞。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 第四步，调整并实践。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>事件\u003c/p>\u003cp>（时间/地点/人物/经过）\u003c/p>\u003c/td>\u003ctd>\u003cp>共性\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>生气\u003c/p>\u003c/td>\u003ctd>\u003cp>周五下午，办公室，小毛，装修方案意见不合。\u003c/p>\u003c/td>\u003ctd>\u003cp>只要是跟小毛讨论问题，就经常会生气。\u003c/p>\u003c/td>\u003ctd>\u003cp>争吵\u003c/p>\u003c/td>\u003ctd>\u003cp>我认为小毛是新人不专业，而自己希望能跟专业的人合作。\u003c/p>\u003c/td>\u003ctd>\u003cp>不欢而散，项目进度停滞。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>不生气\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>只要是跟小毛讨论问题，就经常会生气。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>不争吵，接一杯热水\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>每个人都不完美，团队默契需要磨合。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>换个角度讨论工作，推进进度。\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; \u003cstrong>【预防异议】\u003c/strong>可能你会问，我通过填这个表格就能够对抗负面情绪了嘛？我只是写下来，但是消极情绪一上来自己可能还是控制不住啊！我想我们要了解的是，任何方法都不是速效药，特别是我们已经产生惯性的行为都是需要刻意练习才能改变的。CCEA结构化日志作为情绪管理的工具之一，可以帮助我们有意识地察觉情绪，定期总结，理性反思，改变认知，慢慢地逐步管理好自己的情绪。大家不妨先用一周的时间尝试一下。\u003c/p>","interaction":"\u003cul>\u003cli>\u003cp>\u003cstrong>【A3】\u003c/strong>\u003c/p>\u003c/li>\u003c/ul>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 接下来，我们一起来尝试运用一下刚刚介绍的CCEA结构化日志。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 给大家一个使用场景：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;情绪：愤怒。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 第一个事件，周一时，小A约了男朋友下班后去吃饭看电影，快下班的时候男朋友爽约了，于是电话里面吵了一架，小A斥责他为什么不早说；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;第二件事情，周三上午，男朋友说带小A去餐厅吃饭然后一起看球，到了餐厅见到了他的朋友，全程男朋友都在跟朋友讨论比赛，完全没有理会小A，当时小A没有说什么，但是回去的路上又跟男朋友大吵一架。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 现在请假设自己是小A，接着……\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;为了方便大家练习，我把第一个步骤，也就是情绪、事件、行动和结果先填写好了。接下来，我想请大家以小组为单位，尝试运用刚才介绍的第二、三、四步骤来分析愤怒这一消极情绪背后的事件共性、认知问题，以及如何改变认知，进而改变情绪、改变行为，最后产生好的结果。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;给大家5分钟的时间进行讨论，并把小组讨论结果写在对应的表中，等一下我们请一个组做代表来分享。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>情绪\u003c/td>\u003ctd>\u003cp>事件\u003cbr>\u003c/p>\u003cp>（时间/地点/人物/经过）\u003c/p>\u003c/td>\u003ctd>\u003cp>共性\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>愤怒\u003c/p>\u003c/td>\u003ctd>\u003cp>周一，男友，约好一起吃晚饭，临时放鸽子\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>发火\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>吵架\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>愤怒\u003c/p>\u003c/td>\u003ctd>\u003cp>周三，男友，约了晚上一起吃饭看球，全程只顾跟朋友聊天，不理会自己\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>发火\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>大吵一架，男友也很生气\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>学习者分享案例：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;首先，总结共性。小A一遇到与男朋友不够亲密的时候，她就会很生气。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 然后，分析认知。小A希望男友把自己摆在第一位。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 最后，调整认知和行动。行动目标是不发火，调整结果就是如果男友放了我鸽子，那我就去约其他朋友吃饭玩耍，我也一样很开心，如果男友去看球了，那我就不陪他去了，我找朋友去逛街。也就是找其他事情去转移自己的注意力，让自己可以和男朋友和谐共处。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>情绪\u003c/td>\u003ctd>\u003cp>事件\u003cbr>\u003c/p>\u003cp>（时间/地点/人物/经过）\u003c/p>\u003c/td>\u003ctd>\u003cp>共性\u003c/p>\u003c/td>\u003ctd>\u003cp>行动\u003c/p>\u003c/td>\u003ctd>\u003cp>认知\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>愤怒\u003c/p>\u003c/td>\u003ctd>\u003cp>周一，男友，约好一起吃晚饭，临时放鸽子\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>发火\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>吵架\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>愤怒\u003c/p>\u003c/td>\u003ctd>\u003cp>周三，男友，约了晚上一起吃饭看球，全程只顾跟朋友聊天，不理会自己\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>发火\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>大吵一架，男友也很生气\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cstrong>不愤怒\u003c/strong>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cstrong>与男朋友不够亲密时就会生气\u003c/strong>\u003c/td>\u003ctd>\u003cstrong>不发火\u003c/strong>\u003c/td>\u003ctd>\u003cstrong>希望男友把自己摆在第一位\u003c/strong>\u003c/td>\u003ctd>\u003cstrong>找其他事情转移自己注意力，比如约朋友逛街吃饭玩耍\u003c/strong>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>【反馈·真诚赞美】\u003c/strong>谢谢这位美女姐姐的分享，非常清晰的使用了CCEA结构化日志的二、三、四步，这样分析和调整之后，小A的愤怒情绪就得到了控制。\u003c/p>\u003cul>\u003cli>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003c/li>\u003c/ul>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;接下来，我们一起来完整应用CCEA结构化日志对抗消极情绪并改变自己的行动结果。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>【分步催化】\u003c/strong>回忆过去一周时间，你感受最多的消极情绪是什么？是愤怒，是焦虑，还是沮丧？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;然后回忆一下，引起自己这种消极情绪的事件有什么？是下班后伴侣宁可坐着打游戏，也不帮自己做家务？还是自己辛辛苦苦加班加点完成项目工作，最后评优老板给了其他人？又或者是孩子在学校又调皮捣蛋然后自己被老师请到学校去谈话了？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;选定你过去一周你感受到的消极情绪之一，设想在未来一周如果出现这样的情绪，你会怎么做？你会怎样运用CCEA结构化日志？四个步骤，首先记录情绪、事件、行动、结果，然后总结共性，接着反思认知，最后调整认知，并改变情绪和行动结果。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;接下来给大家每人5分钟的时间，简单运用一下CCEA结构化日志，并写下来。等下我想请一位伙伴来分享一下他的使用计划。\u003c/p>\u003cp>\u003cstrong>学习者分享案例：\u003c/strong>\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;未来一周跟心仪女孩相处时可以用到CCEA结构化日志。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>情绪\u003c/td>\u003ctd>事件（时间/地点/人物/经过）\u003c/td>\u003ctd>共性\u003c/td>\u003ctd>行动\u003c/td>\u003ctd>认知\u003c/td>\u003ctd>结果\u003c/td>\u003c/tr>\u003ctr>\u003ctd>失落\u003c/td>\u003ctd>约心仪的女孩出行，还有家人一起，行程安排不好，出现了曲折\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>不敢再联系对方\u003c/td>\u003ctd>小事都做不好，对方对我印象肯定很差了。想要得到对方的认可。\u003c/td>\u003ctd>关系变冷\u003c/td>\u003c/tr>\u003ctr>\u003ctd>不失落\u003c/td>\u003ctd>未来一周吃饭时，没有点好菜，出游时对方可能不喜欢\u003c/td>\u003ctd>跟女孩相关的事情，都很紧张，担心对方没有被照顾到\u003c/td>\u003ctd>主动联系对方。多考虑她的需求，真实表现自己\u003c/td>\u003ctd>每个人都是不完美的，展现真实的自己就好\u003c/td>\u003ctd>关系更亲密，自在\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; \u003cstrong>【反馈·号召鼓掌】\u003c/strong>感谢这位伙伴的精彩分享，我们再给他一点掌声！\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 【结语】\u003c/strong>今天一共跟大家分享了关于对抗消极情绪的两个片段。第一个片段向大家介绍了CCEA模型（分别指C情景、C认知、E情绪、A行动），以及如何运用CCEA模型分析情绪的源泉——认知，第一步，\u003cstrong>察觉情绪\u003c/strong>，第二步，\u003cstrong>回忆场景，\u003c/strong>第三步，\u003cstrong>回忆行动，\u003c/strong>第四步，\u003cstrong>分析认知。\u003c/strong>第二个片段则向大家介绍了如何使用CCEA结构化日志，反思并调整自己的认知，进而改变消极情绪和行为。第一步，\u003cstrong>每日记录情绪、事件、行动、结果\u003c/strong>；第二步，\u003cstrong>总结事件共性\u003c/strong>；第三步，\u003cstrong>分析认知\u003c/strong>，判断这个认知是不是不正确的、偏激的。第四步，\u003cstrong>调整并实践\u003c/strong>，调整错误的认知，转变情绪，改变行为，最终改变行动结果。最后要强调的是，CCEA模型和结构化日志都是帮助我们察觉和调整情绪的工具，我们要坚持有意识地使用，才会有更大收获。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;今天的分享就到这里，谢谢伙伴们的参与和互动。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1550378793000,"updated_at":1550387037000,"ria":true},{"id":6499,"topic":"理性识别消极情绪","learn_goal":"在消极情绪出现时尽快自我察觉，避免陷入更消极的情况","remark":"《积极达成》是一本非常实用的自我管理类书籍，教授成年人学习如何有效地控制自己的情绪。作者王明伟是一位专注于影响力和领导力领域的培训师，是美国知名影响力与领导力培训机构VitalSmarts公司在大陆地区认证最早的讲师之一，他在本书中提出了一个处理情绪的“4A”模型和处理问题的“PRO”模型，结构清晰，案例生动，容易学习和实践。这本书尅帮助我们学习尽快察觉自己的消极情绪，并学着先处理好自己的消极情绪，转化为积极的局面后，然后再处理好实际事务。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"深寒","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家晚上好，我是深寒。\r\n 【学习目标】今天想带大家一起完成的学习目标是：通过练习，能够在消极情绪出现的时候尽快自我察觉，理性地避免自己陷入更消极的情绪中，进而影响自己的工作、学习和生活。\r\n 【FAB图书介绍】\r\n （F）今天我们学习的这本书是《积极达成：处理好情绪再处理问题》，其作者是一位专注于影响力和领导力领域的培训师，是美国知名影响力和领导力培训机构VitalSmarts公司在大陆地区认证最早和授课最多的职业讲师之一。他在本书中提出了处理情绪的“4A”模型和处理问题的“PRO”模型，结构清晰，案例生动，容易学习和实践。\r\n （A）这本书是一本非常实用的自我管理类书籍，相比于现在许多情绪管理的书籍，这本书把理论用简单的模型呈现出来，让人一目了然，操作步骤也是清晰可实践，并且提供了工作中的实际应用案例，很关键的一点是都是国内的案例，比起很多国外的书提供的国外的案例更加接地气。\r\n （B1）你有没有经历过下面这些情况？听到领导布置任务就开始心里不爽满心怨念结果工作结果不如人意；一站到众人面前就心狂跳不止，额头冒汗，结果重要的场合领导再也没说让你参加；听到另一半抱怨两句生活琐碎就突然炸毛，对对方发火，结果和对方的感情跌至冰点。如果你的答案是肯定的，那么这本书就可以帮助我们学习通过察觉、接受、分析和调整情绪，将消极的情况转化为积极的局面，然后利于事情达成。\r\n （B2）今天学习的片段就是这本书“4A”模型中的第一步：察觉情绪。在情绪产生的那一刻，我们就通过一些方法察觉到它，进而控制住它，避免消极情绪伤人伤己，并且也能降低我们后知后觉再次费尽心思去弥补情绪错误的概率。\r\n 【阅读原书拆页】接下来请大家用2分钟的时间阅读一下拆页内容，阅读结束之后请举手示意一下。现在开始。","ratings_count":1,"texts":[{"id":9815,"quote":"\u003cp>\u003cstrong>当下观察\u003c/strong>\u003c/p>\u003cp>当面对问题时，我们很有可能会出现消极情绪，通过时刻观察自己，识别自己的情绪状态，防止自己过深地陷入情绪当中。以下的方法帮助我们更好地进行当下观察。\u003c/p>\u003cp>\u003cstrong>第一步，用深呼吸的方法让自己集中注意力。\u003c/strong>\u003c/p>\u003cp>集中注意力对于自我观察是相当重要的，因为只有注意力集中了，我们才能有意识地进行观察。如何集中注意力呢？凯利·麦格尼格尔等美国心理学家通过一系列实验发现，深呼吸能够让我们更好地集中注意力。\u003c/p>\u003cp>深呼吸，是指将呼吸频率降低到每分钟4~6次，也就是每次呼吸用10~15秒时间，比平常呼吸要慢一些。只要你耐心一点，加上必要的练习，这一点不难办到。深呼吸，能够为大脑供应更多的氧气，激活理性脑，有助于你集中注意力。深呼吸几分钟之后，你就会感到平静，有控制感，尤其是注意力更加集中。\u003c/p>\u003cp>\u003cstrong>第二步，将注意力从外界的感知转移到自己内在的感知上，找到自己的“情绪信号点”。\u003c/strong>\u003c/p>\u003cp>这是自我观察的关键一步，如果没有注意力的转移，就无法进行自我观察。在自我观察时，自己可以想象把注意力由外界的某个点移动到身体的某个部位（如心脏、腹部或手部等），这个部位对于消极情绪必须是特别敏感的，我们称之为情绪信号点。有的人有了消极情绪（如生气）之后，手心会出汗，难么就可以把手心作为自己情绪变化的信号点。\u003c/p>\u003cp>一旦你选好了某个部位作为你的“情绪变化信号点”，你就可以经常观察它，注意它的变化。如果你有情绪，就会注意到它会出现某些变化，如心跳加快、手心出汗等。根据情绪的强烈程度，观察点的状态会在非常强烈和不强烈之间变化。在你感到平静和愉悦的时候，也可以读出它的状态，你回体验到完全不同的感觉。\u003c/p>\u003cp>随着你读取“情绪变化信号点”技巧不断提高，你会越来越快、越来越准地判断自己是否进入情绪状态。\u003c/p>\u003cp>\u003cstrong>第三步，观察自己当下的情绪状态，重点判断自己是想逃避，还是想与对方进行对抗。\u003c/strong>\u003c/p>\u003cp>集中注意力向内观察时，你就能清楚地感知自己的想法和身体的变化，尤其需要我们感知对发挥影响力最重要的两种情绪：逃避和对抗。\u003c/p>\u003cp>当自己想逃避时，你回发现内心往往有愧疚感或负罪感，有不愿意面对对方或事情的意思，内心往往有这样的独白：“真想尽快结束，真想赶紧离开这儿。”“我该找什么理由离开这里呢？”你的身体会有相应的表现，比如你开始目光飘忽，不愿意直视对方，开始低头等，这些都是自己可以感知到的信号。\u003c/p>\u003cp>当自己想和对方对抗时，你会发现内心往往会有愤怒、批判或想攻击对方的意思，内心往往会有这样的独白：“都是你的错，才搞成现在这个样子！”“我真想揍你一顿，以解心头之气！”“你的想法太烂了，根本不可行！”你的身体会有相应的表现，比如你开始目露凶光，直盯着对方，你开始握拳或者准备用手指来指对方，你的呼吸开始加快，这些都是你自己可以感知的信号。\u003c/p>","explains":"\u003cp>\u003cstrong>（WHY\u003c/strong>\u003cstrong>）\u003c/strong>生活工作中，我们会遇到各种各样的问题，我们会紧张、沮丧、愤怒、郁闷、绝望，我们的外在表现也会随着这些消极情绪发生变化。不管我们是独立承担某项工作，或者与他人交流合作，我们都会发现：带着消极情绪去做事，事情还没做，行动力就减半了，情绪也让我们和他人的关系变得不和谐，直接影响工作结果，更有甚者，可能这么一件事情就被消极情绪毁掉了。为了避免我们被消极情绪缠绕，我们需要在问题出现的时候及时观察自己的情绪，也就是作者所说的“当下观察”。\u003c/p>\u003cp>\u003cstrong>（HOW\u003c/strong>\u003cstrong>）\u003c/strong>如何进行当下的情绪观察呢？作者提供了三个步骤：\u003c/p>\u003cp>\u003cstrong>深呼吸——观察“信号点”——判断情绪。\u003c/strong>\u003c/p>\u003cp>第一步，深呼吸是为了集中注意力，比平时呼吸得慢，比平时吸气足。做深呼吸练习时，我们的注意力会单纯回到这个动作上来，神奇的是，内心也会平静下来。遇到事情时，首先做深呼吸3次。\u003c/p>\u003cp>第二步，观察“信号点”，也就是吧注意力从呼吸上转移到我们的身体某处。比如过度紧张时手心出汗，生气时咬牙切齿。我们记录下这些与情绪对应的信号点，最好写下来，然后就在大脑中形成了一个固定的回路和记忆。随着我们越来越多的练习，下次出现这种情绪时，我们很快就会有所察觉。\u003c/p>\u003cp>第三步，判断情绪。我们可以通过内心独白、身体表现两项来判断自己的情绪，内心提问“我现在有什么情绪？”。总体来说消极情绪可以有两种走向，一种是逃避，走向乡下，一种是对抗，走向向上。\u003c/p>\u003cp>逃避的时候，我们内心是“回退”的状态，内心往往有以下台词“为什么还不结束？”“等下就赶紧撤了！”“我实在是不想做这个，太难了！”，身体的表现会有诸如咬嘴唇，低头，攥衣角，手脚发凉等。逃避对应的一些情绪包括了过度紧张、沮丧和疲惫等。\u003c/p>\u003cp>对抗的时候，我们内心是“往外冲”的状态，内心台词会有“这个人是不是白痴？！”“总是唠唠叨叨到底想干嘛？”身体表现会有攥紧拳头、瞪眼睛、摔东西等。对抗的情绪包括了愤怒、鄙视、抱怨等。\u003c/p>\u003cp>最后我们可以做一个自己的情绪变化表。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>情绪\u003c/td>\u003ctd>内心独白\u003c/td>\u003ctd>外在表现（尤其信号点）\u003c/td>\u003c/tr>\u003ctr>\u003ctd>例:生气\u003c/td>\u003ctd>\u003cp>1）这么点事情都做不好！\u003c/p>\u003cp>2）做不好，还找理由！\u003c/p>\u003c/td>\u003ctd>手心出汗，握拳，拍桌子，用手指指着对方等\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>（如果不这么做的坏处）\u003c/strong>如果我们出现消极情绪的时候没有做当下自我察觉会怎么样？任由消极情绪游走，注意力不集中，思想和行为不受控制，问题还没处理，情绪就主导了一切，会直接影响我们的做事效率和结果，破坏与他人的和谐关系，而我们也会陷入更深的消极当中去。\u003c/p>\u003cp>\u003cstrong>（举例）\u003c/strong>举一个我自己的真实例子，今年3月我因为项目工作事情特别多，一对多的工作模式让我每天要回复很多人同样的问题，某天我早上在微信群里做完了工作说明，中午一个已在群里的同事就给我打电话，问的就是早上说的事情。我当时一听，火气一下子就蹿起来了！直接开火对着电话就把那个同事给喷了“你能不能好好看下群里的消息？大哥我一个问题说很多遍我也会累好嘛！”对方感觉有点蒙了，很无辜弱弱地挂了电话。大概是我声音太大，周围的同事都看着我，大概在他们心里都留下了我很不友善的印象。事后，我反思是因为自己出现的愤怒的情绪，没有及时察觉，让情绪支配了行为，我给这位同事道了歉，表达我只是一时生气，不是在针对他。\u003c/p>\u003cp>反观如果我使用当下观察的三步骤，先做3次深呼吸，拉回注意力；观察自己的身体变化，找到“信号点”——头皮发麻，要紧牙关，然后继续观察，听到自己的内心独白——“有病啊！能不能认真看别人说的东西啊！”——判断情绪走向——对抗。这么一个流程下来，我就会冷静下来，看到原来只是我的想法在作祟，我只是产生了愤怒的情绪，然后我会暂停一会儿再回答我这位同事，或者礼貌地告诉他自己在群里看说明就可以了。\u003c/p>\u003cp>由此可见，当下观察情绪，是情绪管理的第一步也是重要一步。\u003c/p>","interaction":"\u003ch2>A1\u003c/h2>\u003cp>接下来我们进入A1，激活自己经验的环节。\u003c/p>\u003cp>\u003cstrong>（显象提问）\u003c/strong>请认真听下面的词汇，哪一个是你感觉比较熟悉的？郁闷、紧张、焦虑、疲惫、懊恼、愤怒、挫败、敌对……哪个词是你觉得熟悉，或者最近经历过的？请写下这个词，只写一个。\u003c/p>\u003cp>然后，我们回忆一下：\u003c/p>\u003cp>①最近一次感受到这种情绪是什么时候？\u003c/p>\u003cp>②当时发生了什么？\u003c/p>\u003cp>③你当时有怎样的内心独白和外在行为表现？（可以结合情绪变化表来回忆）\u003c/p>\u003cp>④这个事情的结果是怎样的？\u003c/p>\u003cp>我们在小组内分享一下，每人1分钟。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>挫败。两个月时间准备考试，复习的时候感到很挫败，内心的独白是“你努不努力都没有用！”在这种挫败的情绪下，自己就没有好好努力去准备，因为一想到这件事情就会很“丧”。\u003c/p>\u003ch2>A1+\u003c/h2>\u003cp>接下来我们要进行下一个环节，针对你刚才的情绪和经理，如果再遇到这样的情况，我们能够怎样及时察觉自己的情绪？特别是结合今天学到的当下观察情绪的三步骤：深呼吸——观察“信号点”——判断情绪。试验一下这样做之后你的感受是怎样的？\u003c/p>\u003cp>\u003cstrong>（反思加工经验）\u003c/strong>下面给大家3分钟的时间反思一下：\u003c/p>\u003cp>①针对自己刚才分享的消极情绪和经历，你回怎么做，写下你做当下情绪察觉的步骤。需要注意的是，做第三步时，我们要留意内心的独白。\u003c/p>\u003cp>②最后，记录下你这么做的感受，跟之前有怎样的对比。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>情绪：郁闷。\u003c/p>\u003cp>做法：1、深呼吸；2、信号点：心里闷闷，头皮发麻；3、内心提问：我是不是很郁闷、烦躁？能不能冷静下来？\u003c/p>\u003cp>结果：回归理性。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1542374835000,"updated_at":1542378563000,"ria":true},{"id":5429,"topic":"利用4A模型处理情绪","learn_goal":"1-2过级","remark":"","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"江畔月","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>【学习目的】用处理情绪的4A模型，处理自己遇到的消极情绪，更好地解决问题，而不是陷进情绪的泥潭。\u003c/p>\u003cp>大家好！我是江畔月，来自石家庄梧桐分舵。我今天分享的片段来自《积极达成》——处理情绪的4A模型。&nbsp;\u003c/p>\u003cp>《积极达成》重点阐述了“积极调整情绪”和“积极处理问题”的方法，并提供给我们丰富易用的模型工具以及贴近生活的具体应用案例。\r\n当今社会的要求是“快与变”，我们要想适应甚至超越这种苛刻的要求，最基本的条件就是把事情做好，把面对的问题解决好，让结果“积极达成”。\r\n那么如何建立积极的情绪，防止陷入消极的情绪呢？我们需要持续不断的用耳、用眼、用脑去“倾听”更多客观的方面，以及用心的与对方保持良好的关系，学会换位思考。这就需要用到我们今天分享的拆解片段——处理情绪的4A模型。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":8591,"quote":"\u003cp>《积极达成》处理情绪的4A模型\u003c/p>\u003cp>1.&nbsp;Aware识别情绪：\u003c/p>\u003cp>识别情绪是处理情绪的第一步，如果我们都没有识别出情绪，就谈不上处理情绪。\u003c/p>\u003cp>2.Accept接受情绪：接受情绪是疏导情绪，而不是压制或对抗，只有我们接受了自己和他人的情绪，才有可能更加灵活的方式来处理情绪，就像打太极一样，硬碰硬，往往两败俱伤，先接受，然后进行化解才是最高的招式。\u003c/p>\u003cp>3.Analyze分析情绪：分析情绪的关键在于搞清楚情绪的来源，以及什么样的认知导致了我们这样的情绪，只有搞清楚认知，我们才能更好的调整情绪。\u003c/p>\u003cp>4.Adjust调整情绪：调整情绪的关键在于将导致消极情绪的消极认知调整为积极的认知，从而把消极的情绪调整为积极的情绪。\u003c/p>\u003cp>（所选拆页有具备可行动性，且有一定复杂性）\u003c/p>","explains":"\u003cp>人们在有消极情绪，特别是愤怒、焦虑等的情况之下，很难想出好的办法来解决问题，大家可能都有过这样的经历，当明显感到自己处于消极情绪中时，无法让自己集中精力专注地去思考该如何解决一个复杂的问题。另一方面，对问题有了明确的方法，如果带着消极情绪去做，也很难把这个问题处理好。\u003c/p>\u003cp>当意识到我们有消极情绪出现的时候，可以用4A模型分析梳理情绪。\u003c/p>\u003cp>处理情绪的步骤\u003c/p>\u003cp>1.&nbsp;识别情绪：深呼吸，问自己“我现在有什么样的情绪”\u003c/p>\u003cp>2.&nbsp;接受情绪：我接受我现在的情绪，遇到什么样事情有什么样的情绪是正常的。\u003c/p>\u003cp>3.&nbsp;分析情绪：在什么情况下，我的情绪是什么，所以情绪产生\u003c/p>\u003cp>4.&nbsp;调整情绪：我因为有什么样的认知，导致我如何，所以我不陷入消极情绪，我要如何，所以我要做怎么做，通过目标和行动引导将情绪调整为积极。\u003c/p>\u003cp>我的同事小李和男友最近又陷入冷战。男友已经两天没有联系她。她很苦恼，但又不想主动联系男友妥协，问我该怎么办。\u003c/p>\u003cp>我用4A模型帮她进行了分析，她的调整步骤如下：\u003c/p>\u003cul>\u003cli>\u003cp>识别情绪：深呼吸，问自己“我现在有什么样的情绪？”\u003c/p>\u003c/li>\u003cli>\u003cp>接受情绪：我接受我现在的情绪，遇到冷战时他不联系我，我生气是正常的。\u003c/p>\u003c/li>\u003cli>\u003cp>分析情绪：在“我想即使我做错了，作为男人，你都应该心胸大些，包容我，应该先打电话给我道歉”的认知下，我才特别生气。\u003c/p>\u003c/li>\u003cli>\u003cp>调整情绪：我因为有男友必须先妥协道歉的认知，导致我“专横无理的应该”，所以我不陷入责备的漩涡之中，我要试着换位思考，先了解他有什么原因，再做进一步决定”\u003c/p>\u003c/li>\u003c/ul>\u003cp>几天之后她打电话给我，说和男友和好了，原因是男友出差，怕电话解释不清，就想出差回来后好好解释，没有想到她会主动联系自己，误会解开，双方重归于好。\u003c/p>\u003cp>总结：\u003c/p>\u003cp>通过处理情绪的4A模型，可以更好地调节消极情绪，达成积极结果。\u003c/p>\u003cp>（简要提炼原文及行动建议，并用一个实例分析用法）\u003c/p>","interaction":"\u003cp>A1拆书家提问设计\u003c/p>\u003cp>通过读这个拆页和案例分享，我们了解到先调整情绪，后处理问题的重要性。那么，请花2分钟回忆一下有没有过不自觉使用4A模型的实例呢，大家可以先在小组内分享，每人一分钟，分享完毕后，每组选一个人分享，总时间8分钟。\u003c/p>\u003cp>（发出指令，让学习者小组内分享相关经验）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>Mona分享案例：上周三在办公室，Mona遇到了一件特别烦恼的事情，她本来想同情同事的遭遇，结果同事将矛头转向她开始攻击。\u003c/p>\u003cul>\u003cli>\u003cp>识别情绪：深呼吸，感受其他同事在攻击自己的时候，心里难受，开始生气。\u003c/p>\u003c/li>\u003cli>\u003cp>接受情绪：我接受现在的情绪，遇到同事将矛头对准你，有反驳无力时，难免会生气。\u003c/p>\u003c/li>\u003cli>\u003cp>分析情绪：在“我本来是同情你，现在却将矛头转向我”这样的认知下，我特别生气，最重要的是还揪出一大堆以前旧账在翻。\u003c/p>\u003c/li>\u003cli>\u003cp>调整情绪：我有种好心没好报的认知，导致我陷入生气的情绪当中，我要试着不去过多干涉他人，做好倾听，简单符合，避免自己成为别人的炮灰。\u003c/p>\u003c/li>\u003c/ul>\u003cp>最后，她通过认识到4A模型有助于调整消极情绪，通过梳理心里也好受很多，而且以后在遇到类似问题时，也会尝试用此方法解决。\u003c/p>\u003cp>陈陈分享案例：本月陈陈又参加了RIA便签营的挑战，结果有一天忘了写作业，导致自责与生气愤懑。\u003c/p>\u003cul>\u003cli>\u003cp>识别情绪：深呼吸，因为自己周复盘时候竟然发现有一天竟然忘记提交便签作业，没有完成自己设定的任务，就十分沮丧。\u003c/p>\u003c/li>\u003cli>\u003cp>接受情绪：我接受现在的情绪，遇到意外事件，注意力被转移，所以忘记了提交作业。\u003c/p>\u003c/li>\u003cli>\u003cp>分析情绪：在“我本来可以完成自己安排的任务”这样的认知下，我特别生自己的气。\u003c/p>\u003c/li>\u003cli>\u003cp>调整情绪：在我本来可以完成自己安排的任务这样的认知下，意外的情况出现导致我陷入自责当中，然而生气无助于解决问题，提前安排计划，做好预案应对突发事件，避免被意外打扰才是解决之道。\u003c/p>\u003c/li>\u003c/ul>\u003cp>我们生活中总会有许多意外情况出现，意外袭来，我们不要互相责备，而是应该用积极的心态来处理问题，只有情绪舒缓了，你才会越来越轻松！\u003c/p>\u003cp>A2拆书家提问设计\u003c/p>\u003cp>大家分享的案例很精彩，相信大家已经掌握了处理情绪的4A模型，那么，你计划在未来一周如何将它运用起来呢？请写下具体的场景及执行计划，让我们更好的应对消极情绪！要有可衡量和观测的后果。\u003c/p>\u003cp>（发出指令，让学习者小组写下自己的A2）\u003c/p>\u003cp>A2案例：\u003c/p>\u003cp>我最近由于工作学习任务重，导致压了很多的事情没有完成，不免陷入焦虑之中。而这种焦虑带给我的是，孩子不听话或者无理取闹，我就会忍受不了，焦躁脾气不好了。如果我再有发脾气的苗头时，我会用以下4步梳理情绪。\u003c/p>\u003cul>\u003cli>\u003cp>识别情绪：先深呼吸，冷静一下，告诉自己我需要找到我发脾气的缘由是什么，孩子的触发只是一个引爆点而已。我是由于孩子打扰我的工作，而工作又恰恰是我希望在晚上的时间尽早完成的，所以焦躁。\u003c/p>\u003c/li>\u003cli>\u003cp>接受情绪：我接受我的情绪，因为好多事情没做，感觉焦虑，时间不可控，加之孩子吵闹，就会触发我的焦虑和暴躁。\u003c/p>\u003c/li>\u003cli>\u003cp>分析情绪：在“我希望孩子能自己玩，别打扰我工作”的认知下，我就把孩子推给别人，能少管就少管一会，实在不行，就拿着手机陪孩子，貌似认真，但效率的确不高，孩子也得不到应有的关注。\u003c/p>\u003c/li>\u003cli>\u003cp>调整情绪：我可以设置好自己的免打扰时间，更高效的完成工作学习，然后抽出一定时间，放下工作和学习专门陪孩子，通过这样的情感交流，她们也能感受到我的真诚和关爱，而不是边拿手机边回复的敷衍。\u003c/p>\u003c/li>\u003c/ul>\u003cp>结语：\u003c/p>\u003cp>大家应该都写完A2了，希望大家可以把它很好地落实下去，希望我今天的分享能有助于提高你对消极情绪的管理，今天分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1530284408000,"updated_at":1530441188000,"ria":true},{"id":5425,"topic":"用PRO模型解决问题","learn_goal":"1-1过级","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"江畔月","city":"石家庄"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>大家好！我是王莉，我的三个标签是产品经理、80后、终身学习。\u003c/p>\u003cp>我现在从事软件产品经理的工作，主要是分析用户需求，与开发打交道，写各种文档。业余时间是阅读和写作，不过都在初期，需要走的路还很远。相比各位小伙伴，我年龄稍长，但学习是不分年龄的，什么时候开始都不晚，不是吗？做一名终身学习者是我的目标和追求！&nbsp;\u003c/p>\u003cp>走进拆书帮，也是为了更高效的学习，教是为了更好的学，所以我又走在拆书家的进阶之路。和热爱学习的小伙伴们一起成长，因为，一个人虽走的快，但一群人才能走的远。\u003c/p>\u003cp>可能大家第一次听到拆书这个词，“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验，规划具体的运用。&nbsp;\u003c/p>\u003cp>拆书分为个人学习的拆书法，和组织学习的拆书法：个人学习的应用是便签法，让人读一本书，就能达到参加同主题营培训的效果；组织学习的应用是一位拆书家拿一本书，加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。&nbsp;\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，他们在一起吸收书给予的能力，成长蜕变，然后一起释放学习促进者的能量。他们分享，传播，给予，付出。\r\n拆书帮落地形式表现为各地的拆书帮分舵。拆书帮分舵是公益性的青年自发组织起来，一起锻炼把知识转化为自身能力的能力，其使命是帮助更多学习爱好者成长为拆书家，源源不断的壮大拆书家的队伍。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8586,"quote":"\u003cp>我们今天的拆书片段来自《积极达成》P136\u003c/p>\u003cp>主题:用PRO模型解决问题\u003c/p>\u003cp>要想解决好问题，我们必须弄清楚三个关键问题：\u003c/p>\u003cp>1.想清楚“问题是什么”。只有定位清楚问题是什么，才能为下一步解决问题打好基础。如果我们连要解决什么问题都不清楚或者搞错了，解决问题就更加不可能了。\u003c/p>\u003cp>2.搞清楚“原因是什么”，问题往往是一个结果，背后往往有导致问题产生的原因，所以我们要定位到导致问题的原因，才能很好的解决问题。\u003c/p>\u003cp>3.找清楚“对策是什么”。我们在分析清楚导致问题的原因之后，要对症下药的找到决策，才能解决问题。\u003c/p>\u003cp>根据三个步骤总结为解决问题的PRO工具:\u003c/p>\u003cp>第一步，Problem clarification澄清问题，想清楚“问题是什么”？\u003c/p>\u003cp>第二步，Reasons analysis分析原因，搞清楚“原因是什么”？\u003c/p>\u003cp>第三步，Options selection选定方案，找清楚“方案是什么”？\u003c/p>","explains":"\u003cp>想想看，我们身边是不是有这两类人：一类人是处理问题的小能手，这样的人工作高效有条理，还把生活打造的多姿多彩，有滋有味。另一类人就是每天忙忙碌碌，也不见他休息偷懒，但却工作生活一团糟，只是在辛苦忙碌，看不到结果。有一句话叫“结果会告诉你答案”。那结果告诉我们什么答案呢？因为什么导致这两类人存在如此大的差异呢？首先带大家来认识——\u003c/p>\u003cp>1.什么是问题？\u003c/p>\u003cp>处理事情主要是解决问题。要想解决好面对的问题，首先要搞清楚，什么是问题？\u003c/p>\u003cp>问题就是目标和现状的差距。解决问题实际上就是设定目标，发现现状与目标之间的差距。为减少这些特定的差距，寻找记忆中存在或者经过的探索，而形成适当或者是适用的工具的过程。\u003c/p>\u003cp>2.总结I\u003c/p>\u003cp>What:用PRO模型解决问题，找到解决问题之前需确定的三个关键问题。\u003c/p>\u003cp>Why:这个方法可以帮助我们更好的定位问题，以及定位造成问题的原因，对症下药，找到解决方法。如果不用这个方法，我们可能不知道问题是什么，即便搞清楚问题了，也要拿出切实可行的对策，否则，就不能从根本上解决问题。\u003c/p>\u003cp>Where:无论是自己的问题，还是与他人合作时产生的矛盾，当我们面对问题想更好解决时，都可以尝试此方法。\u003c/p>\u003cp>How:具体实施步骤是：\u003c/p>\u003cp>第一步，澄清问题，想清楚问题是什么？\u003c/p>\u003cp>第二步，分析原因，搞清楚原因是什么？\u003c/p>\u003cp>第三步，选定方案，找清楚方案是什么？\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>我一直想健身，可是就是没有行动。随着工作学习任务多，更没有时间锻炼，所以日子在拖延中度过。今年3月份，我的背痛的厉害，让我不得不重新重视锻炼这个问题，想想自己已经半年多没有踏进健身房的门了，真的每天就抽不出半小时锻炼吗？为了督促我锻炼，我还加入了一个健身打卡群，打卡失败押金蒸发那种，有了押金激励我动力很足，想努力拿回自己的钱，可是我还因为一次朋友聚会没有完成打卡。\u003c/p>\u003cp>此事就让我感到特别焦虑，觉得我这么小的事情怎么都坚持不了21天呢？\u003c/p>\u003cp>后来我偶然的机会看到了PRO模型，通过它的引导，我一步步认清我存在的问题，并有了明确的解决方案。\u003c/p>\u003cp>1.澄清问题：日子忙碌，精力不够用，如何在工作之余锻炼身体？\u003c/p>\u003cp>2.分析原因：没有锻炼的习惯，工作忙碌，只能利用碎片化时间行动，可就是没有行动，缺乏动力，经常犯懒，拖延。归根到底还是没有明确的，具体的行动方案，我的努力只停留在口号层级“我要健身，我要锻炼”。\u003c/p>\u003cp>3.选定方案：\u003c/p>\u003cul>\u003cli>\u003cp>利用单杠拉伸背部，锻炼小臂\u003c/p>\u003c/li>\u003cli>\u003cp>睡前平板支撑三次，每次最少1分钟\u003c/p>\u003c/li>\u003cli>\u003cp>每周两次健身房运动，每次一小时瑜伽\u003c/p>\u003c/li>\u003cli>\u003cp>出行三公里内尽量骑车。晚饭后带孩子下楼溜圈，20分钟左右。\u003c/p>\u003c/li>\u003c/ul>\u003cp>通过这样的调整，我现在每天也可以有30分钟的锻炼时间了，周末可以有1小时，通过PRO模型的引导，真的解决了我没有时间健身的问题，而且轻轻松送地坚持了一个多月，身体状况好多了。\u003c/p>\u003cp>A2\u003c/p>\u003cp>有了成功经验以后呢，我就想我是不是可以把它应用在解决我工作低效的问题。&nbsp;我有早计划晚复盘的习惯，可是晚上复盘是总是存在没有完成的任务，一开始焦虑，后来竟习以为常了！有人说，你干嘛这么累，少定点任务不就行了？可我不想减，有压力才有动力啊！\u003c/p>\u003cp>我给自己制定了高效完成一天工作的目标，执行时间就是明天，为此，我需要用PRO模型来梳理我的问题。\u003c/p>\u003cp>1.&nbsp;澄清问题：如何高效完成明天工作计划？\u003c/p>\u003cp>2.&nbsp;分析原因：\u003c/p>\u003cp>以前工作低效的原因是什么呢？频繁被外界打扰，被手机干扰、无法集中精力进行深度工作。工作计划也经常被临时性任务打乱，还有碎片化时间利用不充分。\u003c/p>\u003cp>3.行动方案\u003c/p>\u003cul>\u003cli>\u003cp>列清单，将明天所做的事情列表，标注优先级，给任务加截止时间。临时性任务梳理优先级之后排序处理。\u003c/p>\u003c/li>\u003cli>\u003cp>减少外界干扰。工作时将手机静音，不登录电脑微信，不浏览新闻。利用休息时间，批量处理回复，不重要群里的消息不点开看，不要脑残的只想着消灭小红点。做到只在晚上睡前浏览一次朋友圈，10分钟以内。\u003c/p>\u003c/li>\u003cli>\u003cp>用碎片时间完成小任务（绕口令、读书笔记打卡）。\u003c/p>\u003c/li>\u003c/ul>\u003cp>明天一早把行动方案贴在办公桌旁，督促自己执行，希望明天晚上复盘的时候，我可以骄傲的说，我做到了今日事，今日毕。\u003c/p>\u003cp>希望大家也能将PRO模型用在你遇到的问题上，能够帮你弄清楚解决问题的关键因素，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1530200376000,"updated_at":1530441106000,"ria":true},{"id":3284,"topic":"缓和情绪两步法","learn_goal":"缓和情绪两步法","remark":"","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"光东","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"学习目标：能够掌握缓和情绪两步法，当情绪出现的时候 ，通过两步法，缓和我们的情绪。大家好，我叫邓光东，邓小平的邓，黄继光的光，毛泽东的东，我现在在一家外资企业做产品维修的工作。用三个标签来形容我自己。第一个标签是：读书，自己比较喜欢读书，以前喜欢读经济、心理学、散文等等，现在开始阅读实用性的书籍，觉得对自己帮助也挺大的。第二个标签是旅行，喜欢在路上的感觉，有时是为了放松心情，有时为了开阔视野，有时为了发现自我。第三个标签是思考，自己希望在今后的一段时间中，努力提高自己独立思考的能力。","ratings_count":0,"texts":[{"id":6126,"quote":"\u003cp>在分享段子之前，我简单给大家介绍一下拆书和拆书帮。\u003cbr>“拆书”法是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果,英文缩写RIA,R:阅读原文拆页，I:就是用自己的语言对R部分读到的片段进行解释、翻译或者复述，A:拆为己用，有三种做法，A1是激活学习者经验，经常是过去失败的相关经验；A2是催化学习者未来的应用；A3是促动学习者现场也就是当下的演练；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮分舵是公益性青年组织，其使命是帮助更多的学习爱好者成长为拆书家。\u003cbr>\u003c/p>\u003cp>今天我要晋级的是1-1,这个段子摘自《积极达成》。下面给大家两分钟的时间阅读手中的段子。阅读完毕后，麻烦大家给我举手示意一下。\u003c/p>\u003cp>我们需要在“下判断”和“找原因”后，不要把自己的这些想法作为铁板钉钉的事实，学会质疑我们的“下判断”和“找原因”。作为几百万年的进化结果，我们不可能不去“下判断”和“找原因”，但是只要不把它们当成确定的事实，就不会强烈的影响我们的情绪。比如，在与对方合作时，有些事情对方坚决不答应我们，这时我们的判断很有可能是“这事对我不利”，紧接着归因就可能是“对方故意为难我”，如果我们把这些判断和归因当成确定的事实，我们的情绪肯定好不到哪里去，说不定很快就发飚了，但发飚的结果肯定是事情没解决，人也得罪了。\u003c/p>\u003cp>当我们学会质疑自己的判断和归因后，结果就会不同。加入质疑的环节，质疑判断——“这事真的对我不利吗？还是我太快下结论了？”质疑归因——“他是真的有意为难我吗？还是出于其他原因？”\u003c/p>","explains":"\u003cp>在工作生活中，我们可能经常会碰到情绪不佳导致自己无法处理问题的情况，愤怒、不满、委屈等等负面情绪可能降低我们的判断力，这时情绪的调整是至关重要的。\u003c/p>\u003cp>比如，在工作中，同事对我们的计划提出了不同意见，你可能认为他是故意找茬，不赞同你的计划，那么你就可能感到不爽与愤怒，进而产生敌对的情绪，后续你们针对计划的讨论，就变成了敌我的讨论，可能就会导致两人关系紧张，计划也不能很好的完善。在这里，我们对同事提出的不同意见，急于的“下判断”和“找原因”，让我们的产生了不佳的情绪。\u003c/p>\u003cp>而如果我们对自己的判断和归因加入质疑的环节，我们的情绪就可能得到缓和，让我们考虑得更加周全，以下就是缓和情绪的两个方法：\u003c/p>\u003cp>第一，质疑判断——“是不是我太快下这个结论了？”\u003c/p>\u003cp>第二，质疑归因——“是不是有其他原因？”\u003c/p>","interaction":"\u003cp>大家可能在工作生活当中，或多或少都有遇到急于下判断和找原因，影响了自己情绪的情况吧，看了这个段子，我也联想到了自己的一个经历。有一次，在街上遇到一个女性朋友，微笑着给她打招呼，但她面无表情，没有任何回应，当时心里就有点不舒服，很没有面子，自己主动打招呼，结果却没有得到她的任何回应，觉得她是故意不回应我，觉得会不会是我之前有得罪她，她还记很在心里，所以当时就想以后再也不主动给她打招呼了。如果当时能用文中的方法去质疑我的判断“她故意不回应我？我是不是太快下这个结论了？”， 质疑我的归因“是不是还有其他原因，比如我打招呼的声音太小了？或者说街上人太多，没有看到我？”。加入这样的质疑后，我可能就不会有那么大的不爽了。\u003c/p>\u003cp>这个段子对我的启发很大，为了不过快的陷入情绪中，让自己丧失理性的判断与思考，今后遇到类似情况，我会首先质疑我的判断“是不是我太快下这个结论了”，其次质疑我的归因“是不是有其他原因？”。\u003cbr>今后是在开车过程中，当遇到前车突然变道的情况时，我会使用文中的方法，首先问自己“我认为前车故意变道，这个结论是不是我下得太快了”，然后问自己，“是不是有其他原因导致前车突然变道呢？比如对方是个新手，没有注意到，回顾自己，有时也会出现没有注意到后方变道的情况，或者说他有急事，比较着急”，这样的话，就能缓和自己的情绪，而不是马上产生愤怒的情绪，进而影响自己的心情与行为。\u003cbr>那最后我们再回顾下这个方法：\u003cbr>第一，质疑判断——“是不是我太快下这个结论了？”\u003cbr>第二，质疑归因——“是不是有其他原因？”\u003cbr>希望这个方法让大家也有所收获。今天我的拆解就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500907002000,"updated_at":1503495246000,"ria":true},{"id":1725,"topic":"面对棘手的问题时，掌握影响他人的方法，积极解决问题。","learn_goal":"面对棘手的问题时，掌握影响他人的方法，积极解决问题。","remark":"图书介绍：\r\n如何影响消极工作的下属让他积极地对待工作？\r\n如何影响火冒三丈的客户让他冷静下来处理事情？如何影响叛逆的孩子让他与你达成共识？\r\n此次拆书，助你影响他人，积极达成！","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"小鹿","city":"苏州"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，学习者能够在和别人一起面对棘手的问题时，使用先平静自己再平静他人的方法，积极影响他人。今天拆的书来自《积极达成—处理好情绪再处理问题》。\r\n【F】这是一本情绪管理的实用工具书，教人处理好情绪、再处理问题、最后积极达成，作者是王明伟老师；\r\n【A】与众多情绪类书籍相比，这本书的优势就是在围绕“解决问题”处理自己和他人的情绪，大量翔实的案例分析使得实操性和可信度都很强。\r\n【B】大家都有消极的情绪对嘛？特别是遇到孩子不听话、客户无理取闹、下属消极怠工、男票天天让你喝热水等等情境下，这本书就能帮你平静情绪，找出问题，积极解决问题的同时，获得和谐人际关系！","ratings_count":0,"texts":[{"id":4292,"quote":"\u003cp>毕盛（化名）是一个“85后”的小伙子，在国内某大型商业银行做客户服务代表，工作就是处理客户的投诉。最近他在工作上遇到不少烦心事，不但没有处理好客户的投诉，还连续被客户投诉了好几次。他来找我诉苦，抱怨现在的客户越来越难伺候了，然后跟我说最近工作特别辛苦，得经常加班。\u003c/p>\u003cp>我问他：“当客户给你打电话让你处理问题时，你怎么想？”他没有好气地说：“这些客户鸡毛蒜皮点事情就打电话投诉，真是没事找事，搞得我们每天加班。我真是烦死了。”我又接着问：“那你有没有发现，当你自己这么想时，你跟客户说话的语气语调也发生了变化？”他想了想，不好意思地说：“是，我就会不耐烦地说，这些都是网站上明确写出来的，去查网站就好了，没必要打电话。结果好几次客户都说我态度不好，显得很不耐烦，所以就投诉我了。”\u003c/p>\u003cp>做客户服务工作是最需要发挥影响力，才能达成积极结果的。但毕盛在为客户服务的过程中，并没有调整好自己，没有把自己对待客户的方式调整为合作的方式，而是从内心中排斥（本质上就是一种对抗）客户，所以会以一种对抗的方式来对待客户，这种方式通过他的语气语调等途径被客户感知到，自然客户也就“以牙还牙”，用对抗的方式（投诉）来对待他。\u003c/p>\u003cp>听了毕盛的话，我笑了笑：“其实，做客户服务工作最能锻炼一个人发挥影响力，达成积极结果的能力。要对客户积极发挥影响力，达成结果，有两条秘诀。”他迫不及待地问：“王老师，这真是及时雨啊，您赶紧说吧，别卖关子了。”我说“第一条秘诀，首先要影响和调整自己，让自己以一种帮助客户解决问题（本质上是与客户合作）的方式与客户沟通，而不是嫌客户找麻烦（本质上是与客户对抗）。”毕盛不好意思地点了点头，说：“怪不得被客户投诉呢，原来是我没有调整好自己，自己对待客户的方式就不对，还怪人家客户投诉我。我感觉自己在发挥影响力，积极达成方面真的不及格，第一条就没做到。”\u003c/p>\u003cp>我笑了笑，说：“别灰心，意识到了，就是好的开始。除了你刚才跟我说到的。最近客户给你打电话时，你会怎么处理客户的投诉？”毕盛蛮有自信地说：“简单！客户不就是想解决问题嘛，所以我一般都很直接地问他们是什么情况、想怎么解决，不跟他们太多废话，赶紧解决完。”我又问：“你有没有关注过客户的情绪？”“情绪？没关注过。客户不就是要解决问题吗？”毕盛有点愣住了。我接着问：“按你最近的处理方式，你觉得效果怎么样？”毕盛像霜打了的茄子：“效果不好，不少客户都说我根本不理解他们，因为这个投诉我的客户也不少。”\u003c/p>\u003cp>当我们调整好自己的状态后，下一步就是影响对方了。处理客户投诉是需要我们先去处理客户的情绪，然后再去处理问题的典型过程。在毕盛影响客户的过程中，他也没有意识到处理客户情绪的重要性，而是错误地认为只需要和客户赶紧把事情处理完就可以了。因此，在服务客户的过程中他就没有关注过客户的情绪，结果引起客户更加强烈的情绪反弹，客户投诉他也就不奇怪了。\u003c/p>\u003cp>我说：“发挥影响力，达成积极结果的第二条秘诀就是先处理对方的情绪，等情绪平复了，再处理事情。你回想一下自己的精力，当你在气头上的时候，是不是别人跟你说什么事情都没用？”毕盛点了点头，说：“我自己还真是忽略了关注和处理客户情绪这一步，老是想跨过处理客户情绪的阶段，一步到位的跟客户商量事情怎么处理，现在发现越想跨过处理情绪的阶段就越适得其反。别说关注客户的情绪了，就连我女朋友的情绪我很多时候都关注不到，怪不得她老说我是块儿木头呢。今天我可值了，有两条秘诀在手，工作就不愁了。”\u003c/p>\u003cp>看着毕盛豁然开朗的样子，我说：“还有第三条秘诀，想不想知道？”他赶紧问：“王老师，你说话就像挤牙膏，不一次说完，总吊着我的胃口。”我说：“第三条秘诀就是要在工作中不断去实践刚才讲的两条秘诀。”毕盛说：“一定！一定！”\u003c/p>\u003cp>过了一段时间，我又接到了毕盛的电话，他高兴地告诉我两条秘诀的确起到了作用，最近他做工作开始得心应手了，还说他女朋友也感觉到他更会关心人了。\u003c/p>","explains":"\u003cp>刚刚大家看到的是一个完整的案例，毕盛与客户共同遇到问题，先是处理得一团糟，经王老师点拨后，居然必胜了（这是个笑话请哈哈）王老师究竟有什么神通？！原来是用了“影响他人”这个法宝。\u003c/p>\u003cp>遇到事情，我们可能陷入了焦虑、委屈、生气的情绪中，一味地想让对方接受自己的观点。殊不知，只有做到“影响他人”，他人才能乖乖地与你合作。否则，你说破了天也不会有人来救你的。\u003c/p>\u003cp>所以，影响他人的结果就是积极地解决问题，达成你想要的目的。\u003c/p>\u003cp>【细化行动步骤】\u003c/p>\u003cp>影响他人这么有效，怎么才能影响他人呢？（how和how的how用思维导图展示）\u003c/p>\u003cp>应该做到两个关注：1、关注自己，平复自己的情绪\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2、关注他人，平复他人的情绪\u003c/p>\u003cp>在这里大家可能看到，原文里给出的虽然是how，但是其实是原则性的东西，怎么平复自己的情绪，怎么平复他人的情绪，也是需要行动步骤指导的。这两点在书中都有讲述，此次不做要求，仅为建议，等下在我的栗子中会有部分体现~\u003c/p>\u003cp>栗子来啦！~大家注意听我的应用和平复自己及他人的情绪哦~\u003c/p>\u003cp>我男友老黄又要出场了。老黄一度很反感我来上海拆书，觉得我是很贪玩的不回家的女人。有一天他跟我说我再跑出来就不让我回家。我是很高傲的好嘛，我心想太不理解我了，你自己那么宅还要我陪你宅，我会闷死的，而且我明明很积极向上好嘛。所以我就不理他，或者一下点燃说凭什么，管不着云云。然后俩人就气呼呼的很难受。我看了《积极达成》这本书，有一些感悟，心想着try try吧，所以再次聊这个问题的时候，\u003c/p>\u003cp>我首先平复自己的情绪，问自己三个问题1、是不是我太快下结论了？--是的，毕竟我一下子就来气了；2、是不是有其他原因？--应该是，老黄可能担心我大晚上出事；3、重新思考我的目的—积极地生活，包括正向处理生活中的所有事情。（同时图示平复自己情绪的3个how:质疑--产生认知时，反问自己“是不是我太快下结论了？”“是不是有其他原因？”；积极的目标导向--重新思考我们的真正目的，反复温习”）\u003c/p>\u003cp>然后我平复他的情绪，1、先是表示理解他—哈尼啊，谢谢你，我知道你是为我担心，怕我夜里回来不安全，我真的炒鸡感动的！2、说出我的理由—可是你造嘛，我真的很想参加拆书活动，我觉得这里有我的team，让我有归属感，而且你不觉得参加了拆书活动后，我比之前大有改观吗？3、打消对方疑虑—我造你怕我不安全，酱紫，我拆书前后都会电话你，让你时刻get到我的行动~\u003c/p>\u003cp>然后老黄和我就好了呀~真的好用！~\u003c/p>","interaction":"\u003cp>【A3】促动学习者现场演练\u003c/p>\u003cp>我们刚刚已经清楚了在与别人同时面对问题时，应该要做的两步动作：平复自己的情绪，再影响他人的情绪。在这两步做好基础上去解决问题。现在，我给大家出一道好玩的情景模拟，感受下戏剧学院的feel~\u003c/p>\u003cp>一个寒冷的冬天，5:30你下了班，匆匆赶去离你有1小时的、7:00开始的拆书活动。你饿得能吃下一头牛，想着等下碰到卖吃的我一定要买买买。终于在路上你碰到了一个手抓饼小摊！虽然排队的人有点多，可是放眼望去附近也没有别的吃的卖了。你决定要等。5分钟过去了、7分钟过去了···你的内心很焦灼，一怒之下对小贩发火！小贩这个委屈，就顶嘴了！大战一触即发。\u003c/p>\u003cp>现在，请小组内部角色扮演，一人扮演发火的“吃客”，一人扮演小贩。你们两个人目前面对同一个问题：吃客等了很久一直吃不到饼，责怪小贩，双方都很火大。在1、平复自己的情绪环节，你们可以演出你们的内心活动（独白）。\u003cbr>\u003c/p>\u003cp>请注意，我们的目的并不是要解决情景的问题，而是要做个how的模拟题练练手~所以注意你们的谈话一定要用上how哦~小组还有一人，是观察员，你需要观察他们在这个过程中，是否应用到了how并适时提醒。\u003c/p>\u003cp>给大家5分钟时间，结束后我请2个小组来给大家表演下，请开始吧！\u003c/p>\u003cp>请一组来play下。\u003c/p>\u003cp>请问观察员，你觉得他们的表演在how的应用上如何？\u003c/p>\u003cp>【学习者现场案例】\u003c/p>\u003cp>@Jessica：师傅，我都等了一刻钟了，我快饿死了，手抓饼什么时候能给我呀！\u003c/p>\u003cp>@Reyn：这个要20分钟呢，你看前面排了那么多人，排着好伐！\u003c/p>\u003cp>@Jessica：可是我的活动快开始了呀！烦死了！\u003c/p>\u003cp>@小鹿：ok，现在情绪点到了，请两位使用关注自己再关注他人的方法。\u003c/p>\u003cp>@Jessica：师傅啊我知道你早上很早起来，而且每个都认真地做。可是我饿死了，而且活动已经迟到很多次，他们都已经吐槽我了，实在不想再迟到了。麻烦你帮帮我吧。\u003c/p>\u003cp>@Reyn：那你先找前面的小哥商量下，他不着急先让给你好了。\u003cbr>\u003c/p>\u003cp>@小鹿：谢谢两位！Jessica在平复他人这个部分，3个步骤做得很好！不过在平复自己这个部分没有去做。可能我这个案例点比较低哈，大家一般不会因为这个生气。不过，在真正的生活中，我们会发现，如果不平复自己的情绪，肯定没有心情和能力去平复他人的，对么？不可能在暴怒的情况下，你还在说“我知道你不容易”~所以还是希望大家能够提醒自己，情绪来的时候，先平复自己，再去平复他人。\u003c/p>\u003cp>谢谢大家，希望大家在遇事时，能够坚持利用2个原则控制情绪--先平复自己，再平复他人，什么难题都不是事儿哦~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1483065112000,"updated_at":1483078430000,"ria":true},{"id":1724,"topic":"分析坏情绪，积极调节3","learn_goal":"识别自己的情绪，分析坏情绪来源，并调节成积极的情绪。","remark":"愤怒、委屈、慌张、紧张···坏情绪来了避之不及，上司嫌、下属烦、孩子怕···还谈何影响他人、积极达成？此次拆书，教你识别自己情绪，有效对抗消极。积极人生，就从这一次开始~","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"小鹿","city":"苏州"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，学习者在遇到消极情绪时，能够识别当下的消极认知，并利用策略调节消极认知。书来自《积极达成—处理好情绪再处理问题》。\r\n【F】从书名就能看出，这是一本“情绪管理”书。作者是王明伟老师，王老师拥有10多年的销售高管经验，大家知道销售都是人精啊！然后，王老师转而去做培训师，为众多500强培训领导力和影响力，好评如潮。【A】事实上情绪处理的书很多，经典也不少。但与其他情绪书籍相比，这本书具有鲜明的特色，案例之多，可媲美商学院的“案例教学”。这本书有三大部分：处理自己的情绪、处理他人的情绪，解决问题（今天我们关注在第一部分，处理自己的情绪）。每部分后面都有整整一个章节的“应用”，大量案例涌来，边读故事边应用理论，体验可谓酷爽。\r\n【B】我们凡人在世上都会有这样那样的不爽的，像挤地铁、餐厅等位、项目交流、叫孩子起床、甚至天气不好，也许你想做些改变，让自己宽容大气一点，也让自己做出的决定更加理智。恭喜你，找对了！这本书就能帮你识别消极情绪，定位消极认知，调节成积极情绪后，积极解决问题，同时，获得和谐人际关系！","ratings_count":0,"texts":[{"id":4289,"quote":"\u003cp>\u003cstrong>我们的情绪是急于“下判断”和“找原因”引起的\u003c/strong>\u003c/p>\u003cp>对于眼前的情景，我们的第一反应就是“下判断”，即这个事情对我是好是坏。基于“下判断”的结果，我们就开始产生情绪的变化。当我们面对一些困难时，比如：对方和我们有不同的意见，我们往往会把这种情况看作不好的状况，从而导致不爽的情绪产生。\u003c/p>\u003cp>然后，我们往往会“找原因”，即导致出现当前局面的原因是什么。找原因时，我们往往会犯“基本归因错误”，即对于目前的状况，更容易倾向归因于：是对方怀着不良的目的导致了目前的状况。过去你们的交往经历越是糟糕、后果越是严重，就越容易做出最坏假设，变得生气，并做出莽撞行为。\u003c/p>\u003cp>\u003cstrong>激发消极情绪的还有我们长久以来形成的五种不良认知模式\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;“\u003c/strong>\u003cstrong>专横无理”的“应该”\u003c/strong>\u003c/p>\u003cp>我们认为事情或对方“应该”怎样，或者“必须”怎样。心理学家埃利斯把这种缺少宽容度的心态称为“苛求”，因为我们在心中要求某些事情必须发生或者必须不发生。但这种苛求往往是非常无理的，而且当别人没有按照我们认为“应该”的方式去做时，我们心头的怒火就会冒出来。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>杞人忧天”的想法\u003c/strong>\u003c/p>\u003cp>这也是一种常见的倾向，就是夸大事件的消极后果，尤其指我们把某些自己不喜欢的，不如意的事情看成是糟糕的、可怕的、灾难性的。如果我们带着这种想法去做事情，就会感到沮丧，从而不愿面对。从小小的争执，到不得不与自己厌恶的人在一起共事都可以让我们觉得像一场灾难--只要我们告诉自己：这是一场灾难。如果是严重的问题，由于我们夸大其消极后果并为此惶惶不可终日，就会更加痛苦。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>非黑即白”的思维\u003c/strong>\u003c/p>\u003cp>这是一种看待事物走极端的方式，认为事物要么是好的，要么是坏的，忽略了中间状态。你会把人或事评价为好的或坏的、正面的或负面的、成功的或失败的，并且没有认识到大多数情况既不是美妙绝伦的，也不是惨不忍睹的，而是出于一种中间状态。走极端的看法使我们的思维模式发生扭曲，更容易导致极端的情绪产生，而且让我们无法看到更好的解决问题的方法。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>以偏概全”的习惯\u003c/strong>\u003c/p>\u003cp>我们以有限的依据为基础，对自己和别人得出消极的结论。有时候，仅凭一次经历，我们就用“总是”“从来不”“每个人”这样的绝对的想法来思考。例如，“每当情况开始好转，就总会出乱子”“每次我试图与她沟通，都毫无用处”等。有了这种以偏概全的习惯，我们经常会陷入消极的负面情绪。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>责备他人”的倾向\u003c/strong>\u003c/p>\u003cp>当问题产生时，很多人倾向于归罪于对方的过失。责备别人的问题在于，只会产生痛苦和憎恨，却不能解决问题。实际上，责备对方不但妨碍了我们采取积极的行动来改变处境，而且很有可能破坏双方的关系。\u003c/p>","explains":"\u003cp>【学习目标1】学习者在遇到消极情绪时，能够识别当下的消极认知。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>通过这一段，我们知道，消极情绪的根源是“消极认知”。\u003c/p>\u003cp>而消极认知包括两个大类，分别是“下判断、找原因”和“五大不良认知”，请大家看大屏幕：\u003c/p>\u003cp>第一类，下判断、找原因~\u003c/p>\u003cp>第二类，五大不良\u003c/p>\u003cp>（1）专横无理，觉得人家“应该”如何如何\u003c/p>\u003cp>（2）杞人忧天，怕这怕那怕怕怕怕\u003c/p>\u003cp>（3）非黑即白，要么这样要么那样，都不行？那没办法了\u003c/p>\u003cp>（4）以偏概全，看见一根草，说是全宇宙\u003c/p>\u003cp>（5）责备他人，怪你怪你都怪你！\u003c/p>\u003cp>我们面对不同情境时，可能产生的是两大类六小点的消极认知的集合。\u003c/p>\u003cp>【根据书中脉络给出更贴近实际的例子】\u003c/p>\u003cp>比如说，有一天，一个麻麻下班回家，看到小朋友居然在津津有味地看动画片！麻麻一下被惹怒，当即想：这小子要上天啊！没一次听我的话！这么贪玩肯定是随他爸！\u003c/p>\u003cp>哎，在这里，麻麻说“这小子要上天啊！”就是“下判断”的消极认知，“没一次听过我的话”是以偏概全，“这么贪玩肯定随他爸”是在找原因。\u003c/p>\u003cp>【how细化原文行动建议的步骤】\u003c/p>\u003cp>当然我们今天的目标，是在自己遇到消极情绪时，定位到自己的消极认知。怎么做呢？我们可以问自己3个问题：\u003c/p>\u003cp>比如说2-1拆完，我觉得效果不好，在面对2-2的准备时，我就有了这种认知，害怕讲解不完美、提问不精巧，我要是没过下次就该害怕了，再不过就丢人了，师父真是好可怜我耽误师父的江湖地位了···我很忧愁（消极情绪），我想找出来背后的原因啊，我就问自己三个问题：\u003c/p>\u003cp>1.我的认知是什么？\u003c/p>\u003cp>我2-2可能过不了了\u003c/p>\u003cp>2.我是不是急于“下判断”和“找原因”了？\u003c/p>\u003cp>恩，还没发生呢！我着急下判断了！\u003c/p>\u003cp>3.有哪种不良的认知？&nbsp;\u003c/p>\u003cp>恩！我怕~~应该是犯了“杞人忧天”的认知了！\u003c/p>\u003cp>这样，我就可以定位自己的消极认知是犯了“下判断”和“杞人忧天”这两戒，我就可以对症下药，改掉我在这个情境下的消极认知啦！\u003c/p>\u003cp>【预防性讲解】\u003c/p>\u003cp>大家会不会疑惑这个认知的概况，全面吗？事实上，这里总结的理性认知，可以涵盖生活工作中的大部分情景。也会有非理性认知，比如潜意识里的深层认知--像小时候受到惊吓等，这种消极认知和情绪可能非今天分享能够解决的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验—显像提问\u003c/strong>\u003c/p>\u003cp>请大家回忆一下最近的一个\u003cstrong>消极情绪\u003c/strong>，可能是气愤、委屈、挫败、抑郁、害怕等等，实在让你“不开心”了一把，请在便签纸上写下这个消极情绪。给大家1分钟时间。\u003c/p>\u003cp>然后，发生这个消极情绪，是什么时候，是什么事件？请想一想并形容当时的场景，在小组内分享。给大家2分钟的时间。然后请小伙伴分享。\u003c/p>\u003cp>\u003cstrong>【学习者现场案例】\u003c/strong>\u003c/p>\u003cp>@Jenny：我有一个人生导师，昨天去见他，上2个小时的课程，结果人生导师一直在说我的缺点，我整个感觉烦死了，我又不是不知道我的缺点。结果我后半场都没有说一句话，走的时候直接说“烦死了”。\u003c/p>\u003cp>@小鹿：哇，你有人生导师那么棒！所以Jenny你的消极情绪是烦躁，对么？\u003c/p>\u003cp>@Jenny：是的，就是烦躁。\u003c/p>\u003cp>\u003cstrong>【A1+】催化应用\u003c/strong>\u003c/p>\u003cp>请大家进入刚刚你想到的情绪和事情，假设你回到了过去，你感受到了那种消极情绪后，通过问自己三个问题，找出自己的是何种消极认知呢？\u003c/p>\u003cp>请想一想，在小组内分享，其他成员可以帮助一起挖掘。给大家2分钟时间。然后请1位小伙伴分享。\u003c/p>\u003cp>\u003cstrong>【学习者现场案例】\u003c/strong>\u003c/p>\u003cp>@Peri：我的消极情绪是痛苦，我觉得赋能班太有压力太难了，可能招不满。1、我有没有下判断找原因？确实是，我下判断招不满，原因可能是我没有经验；2、我有没有不良认知？我有，有专横无理—我今天跟桃子见面时说，你应该帮我，桃子回复我说你再这么说就不帮你了；也有杞人忧天；非黑即白没有；以偏概全我觉得有，我一直以自己的视角看这件事；责备他人是有的。\u003c/p>\u003cp>@小鹿：谢谢赋能班的班主任！赋能班也是我们拆书帮很赞的活动~非常好的例子！在这里，我们注意下，什么时候用这个方法—就是在遇到消极情绪的当下。刚刚Peri分享了两个当下—一个是她接到活儿的时候，一个是她今天上午遇到桃子。我们在一感到消极情绪的时候，就要去对应到找消极认知的方法。比如，Peri接到活儿的时候，1、是不是急于下判断找原因？是的，下判断了。2、有什么不良认知？可能是杞人忧天和以偏概全。\u003c/p>\u003cp>非常好！希望大家以后遇到相同的情况时，也能按照刚刚的三个问题，来定位自己的消极认知。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":4291,"quote":"\u003cp>\u003cstrong>调整认知的两个重点\u003c/strong>\u003c/p>\u003cp>利用CCEA模型，把消极的情绪调整为积极的情绪，就需要将消极的认知调整为积极的认知，进而起到调整情绪的作用。调整认知的重点在于两个方面：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 以“积极的目标”为导向，不要陷入急于“下判断”和“找原因”中。当我们遇到问题时，不能急于“下判断”和“找原因”，这样会使自己陷入消极的情绪，我们应该重新思考我们的目的是什么，以目的为导向，不让自己陷入消极的情绪中。\u003c/p>\u003cp>（2）&nbsp;&nbsp; 调整五种“不良认知模式”。前面我们特别分析过有五种不良的认知模式导致了负面的情绪，而且这些负面的情绪往往又带来消极的结果，所以我们需要调整这五种不良的认知模式，进而调整我们的情绪：\u003c/p>\u003cp>l&nbsp; 由“专横无理”的“应该”到“换位思考”\u003c/p>\u003cp>l&nbsp; 由“杞人忧天”的想法到“积极解决”\u003c/p>\u003cp>l&nbsp; 由“非黑即白”的思维到“跳出局限”\u003c/p>\u003cp>l&nbsp; 由“以偏概全”的习惯到“了解情况”\u003c/p>\u003cp>l&nbsp; 由“责备他人”的倾向到“反思自己”\u003c/p>\u003cp>\u003cstrong>调整情绪的话术如下：\u003c/strong>\u003c/p>\u003cp>句式：“我不能偏离我的目标（以目标为导向），我不陷入······（下判断，找原因和五种不良的认知模式），所以我要······（明确目标和五种不良认知模式对应的积极方面）”\u003c/p>","explains":"\u003cp>【学习目标2】学习者在遇到消极情绪、识别当下的消极认知时，能够应用对应策略调节消极认知。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>第一段拆页，我们可以在消极情绪的当下，定位到自己的消极认知。可是仅仅知道消极认知是不够的，就好像知道自己生病了却没药一样，没法把情况好转，对吧？所以，这一段就给出了，定位到消极人之后，怎么转变这些消极认知。策略的对应请看大屏幕！~\u003c/p>\u003cp>1、下判断、找原因--积极的目标导向，提醒自己的初心\u003c/p>\u003cp>2、五大不良\u003c/p>\u003cp>（1）专横无理--换位思考，想想对方的处境\u003c/p>\u003cp>（2）杞人忧天--积极解决，正向解决\u003c/p>\u003cp>（3）非黑即白--跳出局限，找到更多的解决方案\u003c/p>\u003cp>（4）以偏概全--了解情况，了解情景背后的故事\u003c/p>\u003cp>（5）责备他人--反思自己，想想自己是不是错了\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>看到这里，有的小伙伴可能会感觉疑惑：为什么王老师事无巨细要给整理出这6小类消极认知，还对应到了解决方案？介么麻烦！我怎么记得住呢！\u003c/p>\u003cp>【强调不这么做的坏处】\u003c/p>\u003cp>【一般做法】大家想象一下一般面对消极情绪的时候会如何做？比如那个年轻的麻麻，看到儿子看电视。一下子火大，可能会责骂儿子，甚至抓住打一顿。【后果】这样，母子关系可能就不那么和谐，娘俩儿可别谈平等地做朋友了，儿子不躲着你走就算不错了。【正面例子】可是如果麻麻听了今天的分享，火气一上来，就提醒自己利用3个问题找出自己的消极认知--下判断、找原因、以偏概全，然后根据对应的策略去解决--积极的目标导向、了解情况，告诉自己的目标是让孩子健康成长，孩子可能有自己的原因而不是贪玩，也许老师布置了看电视的任务呢。这样，麻麻就能平静情绪，积极与孩子交流，找出孩子看电视的原因了。母子的关系是不是更加和谐美好了呢。\u003c/p>\u003cp>知道了这么大的好处，怎么样，还会觉得麻烦么~\u003c/p>\u003cp>【How】\u003c/p>\u003cp>当然，我们还有一套话术，帮助我们标准化操作，请看大屏幕：\u003c/p>\u003cp>我不能偏离我的目标（以目标为导向），我不陷入······（下判断，找原因和五种不良的认知模式），所以我要······（明确目标和五种不良认知模式对应的积极方面）。\u003c/p>\u003cp>【更贴近实际的栗子】\u003c/p>\u003cp>以我拆书做栗子吧！当我2-1不理想，害怕2-2时，我要这么告诉自己：我不能偏离我掌握拆书能力的目标，我不陷入杞人忧天和下判断，所以我要冷静下来，积极地寻找可以增强自己拆书能力的方法，而不聚焦于2-2的结果。\u003c/p>\u003cp>【预防性讲解】\u003c/p>\u003cp>我之前分享过这个片段，有的小伙伴会觉得对策方面非常模糊，没有行动指导。这一部分会在我以后的片段中分享到。那当下大家可以给到自己一个策略暗示，大脑也会去正向的情绪中寻找方法的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与现场演练\u003c/strong>\u003c/p>\u003cp>刚刚我们学习了消极认知的对应方法，并且用话术自我引导，现在一起做一个演练吧。\u003c/p>\u003cp>请大家认真听一下要演练的场景：\u003c/p>\u003cp>职员麦克是一位销售，他所负责的片区在第三季度下跌30%。大区经理汤姆非常气愤，因为这直接关系到了他的晋升。汤姆质问麦克原因，而麦克认为这并不是自己所能控制的。\u003c/p>\u003cp>\u003cstrong>角色扮演\u003c/strong>：“麦克”“汤姆”“观察员”\u003c/p>\u003cp>请麦克和汤姆\u003cstrong>简单\u003c/strong>演绎对话，\u003cstrong>激发\u003c/strong>消极情绪，情绪到了负面后，告诉自己：停一下！然后\u003cstrong>使用话术\u003c/strong>进行\u003cstrong>内心独白\u003c/strong>，找\u003cstrong>出消极认知并转而积极\u003c/strong>。观察员负责监控在整个过程中，角色是否应用到了话术并适时提醒。\u003c/p>\u003cp>\u003cstrong>请注意\u003c/strong>：演绎只是为了进入消极情绪，\u003cstrong>重点是用话术进行演练\u003c/strong>。\u003c/p>\u003cp>给大家6分钟的时间进行演练，然后我请几个小组为大家演绎。\u003c/p>\u003cp>\u003cstrong>【学习者现场案例】\u003c/strong>\u003c/p>\u003cp>@华俊：麦克！你看看你这业绩！30%下跌！什么概念！\u003c/p>\u003cp>@大鹏：经理你看，咱们行业不好，好多企业都关门了，我已经是做得很好的了！\u003c/p>\u003cp>@华俊：别人怎么样跟你有关吗！你有没有想好自己要做什么！\u003c/p>\u003cp>@大鹏：我已经使出洪荒之力了！你也没有给我资源啊！\u003c/p>\u003cp>@华俊：你要是想不出来解决方案，就给我卷铺盖走人！\u003c/p>\u003cp>@小鹿：很好！现在告诉自己停一下，用话术！\u003c/p>\u003cp>@大鹏：我不能偏离我的目标，我要达到100%的业绩，我不陷入责备他人，有很多方面是我没做好，所以我这周要打电话给我的优质客户，再梳理和深挖需求，达到我的100%的业绩目标。\u003c/p>\u003cp>@小鹿：很好！汤姆来！\u003c/p>\u003cp>@华俊：我不能偏离我的目标，我的目标是是目标完成率最高。我不陷入责备他人，我可能没考虑到是不是给到下属足够的资源和支持。所以我要组织一个解决方案，使后续的损失降到最少。\u003c/p>\u003cp>@小鹿：谢谢两位精湛的演技，也都非常准确地应用了我们的话术。我们现在来回顾下。刚刚麦克在生气时，告诉自己：我不能偏离我的目标，我的目标是100%完成指标。刚刚谈话中，麦克说“大环境不好啊”，其实是一种“找原因”的消极认知，对么？（点头）所以麦克的话术下一句可以是，我不陷入找原因和责备他人的消极认知中。所以我要有积极的目标导向，反思自己的不对；我之前可能并没有投入很高的精力去做业绩，我要打电话给优质客户再增业绩。这样就是完整的话术，也通过话术，镇定了情绪，并且找出了下一步计划。\u003c/p>\u003cp>然后再来看看汤姆上司。我不能偏离我的目标，这个目标可能是团队和谐、业绩达成，对吧？（点头）我不能陷入消极认知，包括责备他人、蛮横无理、非黑即白（你刚刚有说做不好就走人），所以我要反思自己、换位思考、跳出局限，比如想想自己是不是有支持不到位的地方，想想麦克是不是有不得已的苦衷，帮助麦克想想有什么较好的解决办法。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>刚刚的现场应用大家做得很棒！我们先是用3个问题找到自己的消极认知，再通过话术定位相应策略，获得积极心态和情绪。刚刚也通过现场试用使大家熟悉了用法。那今天学到的东西怎么应用于\u003cstrong>自己的\u003c/strong>生活工作中呢？\u003c/p>\u003cp>请大家想一想，年底了，最近你要跟进哪件事情，这间事情可能会引起你的消极情绪？比如年度总结、项目跟进、孩子期末考试等等。\u003c/p>\u003cp>请大家想到一个具体的事情，想想，你将如何利用今天学习的知识识别消极情绪，积极面对？\u003c/p>\u003cp>请拿出一张便签，写下接下来你会经历的事件，以及你的行动计划，请写下具体的使用时间、事件、行动方案等。注意要应用今天学习的3个问题、话术。给大家3分钟的时间。\u003c/p>\u003cp>写好的小伙伴可以在小组内分享，给大家2分钟时间。然后我请几位小伙伴为大家分享。\u003c/p>\u003cp>\u003cstrong>【学习者现场案例】\u003c/strong>\u003c/p>\u003cp>@Patrick：12月27号晚上6:30，我将跟表弟吃饭。表弟最近家里出事了，到时候可能气氛不好。我可能陷入了杞人忧天的消极情绪，所以我要积极解决，想想看我能为我表弟做些什么。\u003c/p>\u003cp>@小鹿：很好的例子。那担心的时候，你要告诉自己：我不能偏离我的目标，我的目标是和表弟好好相处。我不陷入杞人忧天，所以我要积极解决，想想未能为表弟做什么。对吧？希望能够帮助到你。\u003c/p>\u003cp>\u003cstrong>【学习者现场案例】\u003c/strong>\u003c/p>\u003cp>@小悦悦：下两个礼拜，我会不停面试，可能会失败然后沮丧。我会想：大公司怎么就不能给年轻人一点机会呢，我可能年前找不到工作啦！这时我可能陷入了下判断、杞人忧天和以偏概全的消极认知。所以我会用话术，告诉自己，我要积极地找工作，不断地投试，多了解公司和市场情况，帮助自己摆脱消极认知，平复情绪。\u003c/p>\u003cp>@小鹿：很好，那么在遇到沮丧的心情时，你要迅速定位到自己的不良认知，比如以偏概全、杞人忧天，然后再对应到相应的解决方案。祝你找工作顺利哦！\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>今天结束，大家在遇到消极情绪的时候，生气、难受的时候，都可以在内心喊自己：停一下！~然后想想这3个问题，挖掘自己是不是陷入了消极认知？然后通过话术，找出对应消极认知的策略。这样，大家很快就会发现，消极情绪不见了，我似乎变得更加理智了。而且还有积极的行动计划！这样大家一方面从消极中脱离出来，一方面又能积极解决问题，保持年轻，保持成功！大家持续使用，就能形成习惯哦！加油！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1483064823000,"updated_at":1483078974000,"ria":true},{"id":1657,"topic":"分析坏情绪，积极调节2","learn_goal":"识别自己的情绪，分析坏情绪来源，并调节成积极的情绪。","remark":"愤怒、委屈、慌张、紧张···坏情绪来了避之不及，上司嫌、下属烦、孩子怕···还谈何影响他人、积极达成？此次拆书，教你识别自己情绪，有效对抗消极。积极人生，就从这一次开始~","level":"TF2-4","duration":50,"status":0,"type":0,"chaishujia":{"username":"小鹿","city":"苏州"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"大家好！我是小鹿~感谢大家参与我的分享~请小伙伴们4人一组吧！\r\nFAB法介绍书本（2分钟）\r\n今天拆的书来自《积极达成—处理好情绪再处理问题》。\r\n【F】从书名就能看出，这是一本情绪管理工具书。这本书的内容是：教人先处理自己的情绪，再处理他人的情绪，最后积极达成、解决问题。今天咱们学习最基础的：处理自己的情绪。\r\n本书认为，处理情绪是基于CCEA的模型：\r\n情景触动个人认知，认知引发情绪，情绪促进行动，行动导致结果。这是因果逻辑。\r\n由于情景客观不可变，个人就需要调整认知，使之积极，从而促动积极的情绪和行动。整本书就是基于这个模型，针对各个环节进行自我影响、他人影响和解决难题。\r\n【A】本书作者是王明伟老师，此人拥有丰富的销售经验和HR经验，书的内容也因此具有很强的实战性，描述问题和解决方案后，下一页就有相应的案件，令读者边看边学边结合自身，犹如身临其境。比起光有说教木有实例的书，这本可谓非常之酷爽。\r\n【B】大家都有消极的情绪对嘛？特别是遇到孩子不听话、客户无理取闹、下属消极怠工、男票天天让你喝热水等等情境下，这本书就能帮你平静情绪，找出问题，积极解决问题的同时，获得和谐人际关系！","ratings_count":0,"texts":[{"id":4216,"quote":"\u003cp>\u003cstrong>我们的情绪是急于“下判断”和“找原因”引起的\u003c/strong>\u003c/p>\u003cp>对于眼前的情景，我们的第一反应就是“下判断”，即这个事情对我是好是坏。基于“下判断”的结果，我们就开始产生情绪的变化。当我们面对一些困难时，比如：对方和我们有不同的意见，我们往往会把这种情况看作不好的状况，从而导致不爽的情绪产生。\u003c/p>\u003cp>然后，我们往往会“找原因”，即导致出现当前局面的原因是什么。找原因时，我们往往会犯“基本归因错误”，即对于目前的状况，更容易倾向归因于：是对方怀着不良的目的导致了目前的状况。过去你们的交往经历越是糟糕、后果越是严重，就越容易做出最坏假设，变得生气，并做出莽撞行为。\u003c/p>\u003cp>\u003cstrong>激发消极情绪的还有我们长久以来形成的五种不良认知模式\u003c/strong>\u003c/p>\u003cp>除了“下判断”和“找原因”之外，导致我们产生负面情绪的，还有长久以来形成的不良认知模式，这里要跟大家分享五种主要的不良认知模式。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>专横无理”的“应该”\u003c/strong>\u003c/p>\u003cp>我们认为事情或对方“应该”怎样，或者“必须”怎样。心理学家埃利斯把这种缺少宽容度的心态称为“苛求”，因为我们在心中要求某些事情必须发生或者必须不发生。但这种苛求往往是非常无理的，而且当别人没有按照我们认为“应该”的方式去做时，我们心头的怒火就会冒出来。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>杞人忧天”的想法\u003c/strong>\u003c/p>\u003cp>这也是一种常见的倾向，就是夸大事件的消极后果，尤其指我们把某些自己不喜欢的，不如意的事情看成是糟糕的、可怕的、灾难性的。如果我们带着这种想法去做事情，就会感到沮丧，从而不愿面对。从小小的争执，到不得不与自己厌恶的人在一起共事都可以让我们觉得像一场灾难--只要我们告诉自己：这是一场灾难。如果是严重的问题，由于我们夸大其消极后果并为此惶惶不可终日，就会更加痛苦。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>非黑即白”的思维\u003c/strong>\u003c/p>\u003cp>这是一种看待事物走极端的方式，认为事物要么是好的，要么是坏的，忽略了中间状态。你会把人或事评价为好的或坏的、正面的或负面的、成功的或失败的，并且没有认识到大多数情况既不是美妙绝伦的，也不是惨不忍睹的，而是出于一种中间状态。走极端的看法使我们的思维模式发生扭曲，更容易导致极端的情绪产生，而且让我们无法看到更好的解决问题的方法。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>以偏概全”的习惯\u003c/strong>\u003c/p>\u003cp>我们以有限的依据为基础，对自己和别人得出消极的结论。有时候，仅凭一次经历，我们就用“总是”“从来不”“每个人”这样的绝对的想法来思考。例如，“每当情况开始好转，就总会出乱子”“每次我试图与她沟通，都毫无用处”等。有了这种以偏概全的习惯，我们经常会陷入消极的负面情绪。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>责备他人”的倾向\u003c/strong>\u003c/p>\u003cp>当问题产生时，很多人倾向于归罪于对方的过失。责备别人的问题在于，只会产生痛苦和憎恨，却不能解决问题。实际上，责备对方不但妨碍了我们采取积极的行动来改变处境，而且很有可能破坏双方的关系。\u003c/p>","explains":"\u003cp>What\u003c/p>\u003cp>【给出更贴近实际的例子】\u003c/p>\u003cp>这一段，讲述的是消极情绪的根源--消极认知\u003c/p>\u003cp>消极认知包括两个大类，分别是“下判断、找原因”和“五大不良认知”\u003c/p>\u003cp>1、下判断、找原因\u003c/p>\u003cp>这是非常常见的不良认知，就像我刚刚跟大家分享的回家看见孩子在看电视的例子，我们脑子里就立刻下了一个判断：这小子不想好了！立马找了个原因：一定是不想做作业、贪玩！从而引发消极情绪，后果自然不是想要的~\u003c/p>\u003cp>2、五大不良\u003c/p>\u003cp>（1）专横无理，觉得人家“应该”如何如何\u003c/p>\u003cp>这种认知好像在男女关系里很常见，比如女生总觉得男生“应该”照顾我，吵架了“应该”他来哄我，没做到？！你不爱我！分手！\u003c/p>\u003cp>（2）杞人忧天，怕怕怕怕怕怕\u003c/p>\u003cp>这种认知我有体会，2-1拆完，我觉得效果不好，在面对2-2的准备时，我就有了这种认知，害怕讲解不完美、提问不精巧，我要是没过下次就该害怕了，再不过就丢人了，师父真是好可怜我耽误师父的江湖地位了···恩，这就很典型。\u003c/p>\u003cp>（3）非黑即白，要么这样要么那样，都不行？完了完了惨了\u003c/p>\u003cp>有了这种认知，往往感觉自己陷入了两难的境地。比如一家公司大裁员，王经理首席裁去了50%的人，结果活儿还是一样多，相当于他的工作量增加了一倍。压力啊！他就想：要不然就招新人，要不然就自己玩命儿干累死，可是前者公司不从，后者自己不甘。愁死个人咯！\u003c/p>\u003cp>（4）以偏概全，看见一根草，说是全宇宙\u003c/p>\u003cp>这种认知也蛮常见的。再比如我刚刚说的看见孩子看电视的例子，看见一次你就说人家贪玩，这难道不是以偏概全的认知么？~\u003c/p>\u003cp>（5）责备他人，都是你的问题！\u003c/p>\u003cp>这种认知在成人的世界里也很常见呀！比如，小周向另外一个部门收集材料，他发邮件给了小林，说是两天后提交。可是两天后催交无果，小周气死了，他觉得都怪小林，不配合自己让自己出丑。\u003c/p>\u003cp>【异议预防】\u003c/p>\u003cp>我刚刚举了这二大类消极认知的具体案例，帮助大家理解认知的内容。从我刚刚举的例子中大家可以看到，两大类消极认知并不是完全独立的，常常相伴相随，五大不良也可能交叉在我们的认知中体现。作者这样的分类仅仅是为了统筹，让我们了解我们的消极认知都有哪些。\u003c/p>\u003cp>【细化行动建议的步骤】\u003c/p>\u003cp>遇到消极情绪时，为了定位我们的不良认知，我们需要问自己3个问题：\u003c/p>\u003cp>1. 我基于目前状况的认知是什么？\u003c/p>\u003cp>2. 我是不是急于“下判断”和“找原因”了？\u003c/p>\u003cp>3. 是不是有不良的认知模式在作祟？\u003c/p>\u003cp>2-1拆完后，我觉得不理想，觉得自己可能2-2不来噻，很害怕自己过不了。我的情绪是害怕。这是我的例子。\u003c/p>\u003cp>我问自己三个问题：\u003c/p>\u003col>\u003cli>\u003cp>我基于目前状况的认知是什么？\u003c/p>\u003c/li>\u003c/ol>\u003cp>我2-2可能过不了了\u003c/p>\u003col>\u003cli>\u003cp>我是不是急于“下判断”和“找原因”了？\u003c/p>\u003c/li>\u003c/ol>\u003cp>恩，还没发生呢！我着急下判断了！\u003c/p>\u003col>\u003cli>\u003cp>是不是有不良的认知模式在作祟？&nbsp;\u003c/p>\u003c/li>\u003c/ol>\u003cp>恩！我怕~~应该是犯了“杞人忧天”的认知了！\u003c/p>\u003cp>这样，我就可以定位自己的消极认知是犯了“下判断”和“杞人忧天”这两戒，我就可以对症下药，改掉我在这个情境下的消极认知啦！\u003c/p>","interaction":"\u003cp>【A1】激活经验—显像提问（3分钟）\u003c/p>\u003cp>请认真听这些词汇，哪一个让你感觉熟悉--生气、懊恼、挫败、委屈、抑郁、紧张、愤怒、害怕···哪个词是你熟悉的，是你近期经历过的？请在便签纸上写下这个词。\u003c/p>\u003cp>然后，你最近一次感受到这种情绪，是什么时候，是什么事情？请想一想，在小组内分享。给大家2分钟的时间。2分钟后请1位小伙伴分享。\u003c/p>\u003cp>【A1+】催化应用（3分钟）\u003c/p>\u003cp>请大家进入刚刚你想到的情绪和事情，假设你回到了过去，你感受到了那种消极情绪后，怎么问自己三个问题，找出自己的消极认知呢？\u003c/p>\u003cp>请想一想，在小组内分享。给大家2分钟时间。2分钟后请1位小伙伴分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":4217,"quote":"\u003cp>\u003cstrong>调整认知的两个重点\u003c/strong>\u003c/p>\u003cp>利用CCEA模型，把消极的情绪调整为积极的情绪，就需要将消极的认知调整为积极的认知，进而起到调整情绪的作用。调整认知的重点在于两个方面：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 以“积极的目标”为导向，不要陷入急于“下判断”和“找原因”中。当我们遇到问题时，不能急于“下判断”和“找原因”，这样会使自己陷入消极的情绪，我们应该重新思考我们的目的是什么，以目的为导向，不让自己陷入消极的情绪中。\u003c/p>\u003cp>（2）&nbsp;&nbsp; 调整五种“不良认知模式”。前面我们特别分析过有五种不良的认知模式导致了负面的情绪，而且这些负面的情绪往往又带来消极的结果，所以我们需要调整这五种不良的认知模式，进而调整我们的情绪：\u003c/p>\u003cp>l&nbsp; 由“专横无理”的“应该”到“换位思考”\u003c/p>\u003cp>l&nbsp; 由“杞人忧天”的想法到“积极解决”\u003c/p>\u003cp>l&nbsp; 由“非黑即白”的思维到“跳出局限”\u003c/p>\u003cp>l&nbsp; 由“以偏概全”的习惯到“了解情况”\u003c/p>\u003cp>l&nbsp; 由“责备他人”的倾向到“反思自己”\u003c/p>\u003cp>\u003cstrong>调整情绪的话术如下：\u003c/strong>\u003c/p>\u003cp>句式：“我不能偏离我的目标（以目标为导向），我不陷入······（下判断，找原因和五种不良的认知模式），所以我要······（明确目标和五种不良认知模式对应的积极方面）”\u003c/p>","explains":"\u003cp>哈哈，拆页很短又很干，木事儿，听我娓娓道来！~\u003c/p>\u003cp>What&amp;Why（包括一般做法-坏处-正面例子）\u003c/p>\u003cp>这一段是在教我们调整认知成为积极的状态。包括两大类消极认知的对策和调整情绪的话术。\u003c/p>\u003cp>首先我们来看，应对两大难题，n个对策！请看大屏幕！~\u003c/p>\u003cp>1、下判断、找原因--积极的目标导向\u003c/p>\u003cp>意识到自己是在“下判断、找原因”，就得立马提醒自己积极的目标导向。【不这么做的坏处】看到孩子看电视，妈咪破口大骂，是会摧毁小朋友的幼小心灵，疏远母子关系的。如果麻麻提醒自己“我的目标是教导孩子天天向上，而不是生气发火的”可能妈妈就会好好说话，而不是打骂。这样，母子关系岂不融洽，孩子岂不向上？~\u003c/p>\u003cp>2、五大不良\u003c/p>\u003cp>（1）专横无理--换位思考\u003c/p>\u003cp>谈恋爱的女生总是蛮横无理地要求“你应该来哄我，不来？你不爱我，分手！”，这俩人还能好么，女的恐怕要灭绝师太了。如果定位到自己的消极认知--专横无理，然后对照相应的策略改变，换位思考，想想男生是不是有苦衷有理由？电话一打，一和好，甜甜蜜蜜嘛。\u003c/p>\u003cp>（2）杞人忧天--积极解决\u003c/p>\u003cp>心惊胆战之余，能够通过片段一的3个问题意识到自己在“杞人忧天”，并用积极解决的心态暗示自己，平复情绪\u003c/p>\u003cp>（3）非黑即白--跳出局限\u003c/p>\u003cp>如果被裁员的王经理，总是被局限在一个方框里，觉得除了招新人就是自己累死，他估计会压力特别大甚至影响健康。但意识到自己的消极情绪--非黑即白时，王经理可以跳出局限，如跟自己的直属上司沟通，看看是否可以请上司画出业务重点、利用上司的资源拓展业务，跳出局限，事情解决了，也不至于愁死啊！~\u003c/p>\u003cp>（4）以偏概全--了解情况\u003c/p>\u003cp>以偏概全很容易冤枉对方，让对方委屈生气。意识到自己在以偏概全，就可以暗示自己，多去了解各方面的情况，平复自己的情绪。\u003c/p>\u003cp>（5）责备他人--反思自己\u003c/p>\u003cp>小周向跨部门的小林要资料，小林没给。小周一味地责备他人，势必自己的人际关系出错。如果认识到自己在责备他人，小周能反思自己：我这个行政流程对么，是不是要跟小林的上司打个招呼？是不是要走oa？我发了邮件咋不打电话呢？这样同事关系岂不美哉？\u003c/p>\u003cp>这样，利用对应的对策解决相应的认知，对症下药，条理清晰。可以把当下的消极情绪逆转，将事态向好的方向发展。\u003c/p>\u003cp>How\u003c/p>\u003cp>我们仍旧有一套话术，促使我们应用到以上的学习，催化积极情绪的产生，请看大屏幕：\u003c/p>\u003cp>我不能偏离我的目标（以目标为导向），我不陷入······（下判断，找原因和五种不良的认知模式），所以我要······（明确目标和五种不良认知模式对应的积极方面）。\u003c/p>\u003cp>【更贴近实际的讲解】\u003c/p>\u003cp>以我拆书做栗子吧！当我2-1不理想，害怕2-2时，我要这么告诉自己：我不能偏离我掌握拆书能力的目标，我不陷入杞人忧天和下判断，所以我要冷静下来，积极地寻找可以增强自己拆书能力的方法，而不聚焦于2-2的结果。\u003c/p>\u003cp>【异议预防】\u003c/p>\u003cp>我之前分享过这个片段，有的小伙伴会觉得对策方面非常模糊，没有行动指导。这一部分会在以后的片段中分享到。那当下大家可以给到自己一个策略暗示，大脑也会去正向的情绪中寻找方法的。\u003c/p>","interaction":"\u003cp>【A3】促动参与现场演练（16分钟）\u003c/p>\u003cp>刚刚我们学习了消极认知的对应方法，并且用话术自我引导，现在一起做一个演练吧。\u003c/p>\u003cp>请大家认真听一下要演练的场景：\u003c/p>\u003cp>职员麦克是一位销售，他所负责的片区在第三季度下跌30%。大区经理汤姆非常气愤，因为这直接关系到了他的晋升。汤姆质问麦克原因，而麦克认为这并不是自己所能控制的。\u003c/p>\u003cp>请小组内一人扮演麦克，一人扮演上司汤姆，可简单演绎两人的对话。然后请记住自己当下的消极情绪，并用话术演练，使认知和情绪转而积极。请注意，演绎只是为了进入消极情绪，重点是用话术进行演练。小组还有一人扮演观察员的角色，观察二人的演绎，确保重点在话术的应用上。\u003c/p>\u003cp>给大家6分钟的时间进行演练，然后我请几个小组为大家演绎。\u003c/p>\u003cp>【A2】催化应用（13分钟）\u003c/p>\u003cp>刚刚的现场应用大家做得很棒！我们先是用3个问题找到自己的消极认知，再通过话术定位相应策略，获得积极心态和情绪。刚刚也通过现场试用使大家熟悉了用法。那今天学到的东西怎么应用于自己的生活工作中呢？\u003c/p>\u003cp>请大家想一想，与另一半相处、教育小孩、领导下属···你在生活和工作中会涉及哪个场景？\u003c/p>\u003cp>请大家想到一个具体的场景，想想，你将如何利用今天学习的知识改善消极情绪，积极面对？\u003c/p>\u003cp>请拿出一张便签，写下接下来你会涉及的场景，以及你的行动计划，请写下具体的使用时间、场景、操作方式。注意要应用今天学习的拆页。给大家2分钟的时间。\u003c/p>\u003cp>写好的小伙伴可以在小组内分享，给大家2分钟时间。然后我请几位小伙伴为大家分享。\u003c/p>\u003cp>【总结】（1分钟）\u003c/p>\u003cp>大家的例子都很贴切。我甚欣慰~大家刚刚已经做好计划咯，当遇到难题情绪负向时，先通过问自己3个问题，寻找自己的消极认知，再通过话术，套用针对消极认知的策略，转变成为积极认知，促进积极情绪，达成积极结果。不要忘记持续使用哦~谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1482302782000,"updated_at":1482302981000,"ria":true},{"id":1656,"topic":"分析坏情绪，积极调节","learn_goal":"识别自己的情绪，分析坏情绪来源，并调节成积极的情绪。","remark":"愤怒、委屈、慌张、紧张···坏情绪来了避之不及，上司嫌、下属烦、孩子怕···还谈何影响他人、积极达成？此次拆书，教你识别自己情绪，有效对抗消极。积极人生，就从这一次开始~","level":"TF2-4","duration":50,"status":0,"type":0,"chaishujia":{"username":"小鹿","city":"苏州"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"大家好！我是小鹿~感谢大家参与我的分享~刚刚大鹏分享了和自己的沟通，我的分享也是专注于自己哦~\r\n你今天有消极的情绪吗？愤怒、委屈、尴尬，我们好像每天都能遇到很难受的情绪，好像自己不受控制了，做出的决定也就不那么理性了，往往现在想想，唉，悔不当初啊！所以今天，我给大家带来了大礼：控制好自己的情绪，把消极变积极。抱着积极的情绪和态度，万事不难！~请小伙伴们4人一组吧！\r\n今天拆的书来自《积极达成—处理好情绪再处理问题》。\r\n【F】从书名就能看出，这是一本情绪管理工具书。得益于情绪管理经典和丰富的职场案例，作者王明伟老师总结出了情景到行动的CCEA模型\r\n[图片]\r\n认为情景触动个人认知，认知引发情绪，情绪促进行动，行动导致结果。这是因果逻辑。\r\n比如，你下班回家看到孩子不写作业反而在看电视（情景），你觉得这个孩子也太不上进了（认知），一下子火蹿起来（情绪），打了他一顿（行动）。这就是CCEA和实际的结合。是不是很科学？根据此书，所有行动都可以用此模型分析，挖掘认知根源。\r\n由于情景客观不可变，个人就需要调整认知，使之积极，从而促动积极的情绪和行动。整本书就是基于这个模型，针对各个环节进行","ratings_count":0,"texts":[{"id":4214,"quote":"\u003cp>\u003cstrong>我们的情绪是急于“下判断”和“找原因”引起的\u003c/strong>\u003c/p>\u003cp>对于眼前的情景，我们的第一反应就是“下判断”，即这个事情对我是好是坏。基于“下判断”的结果，我们就开始产生情绪的变化。当我们面对一些困难时，比如：对方和我们有不同的意见，我们往往会把这种情况看作不好的状况，从而导致不爽的情绪产生。\u003c/p>\u003cp>然后，我们往往会“找原因”，即导致出现当前局面的原因是什么。找原因时，我们往往会犯“基本归因错误”，即对于目前的状况，更容易倾向归因于：是对方怀着不良的目的导致了目前的状况。过去你们的交往经历越是糟糕、后果越是严重，就越容易做出最坏假设，变得生气，并做出莽撞行为。\u003c/p>\u003cp>\u003cstrong>激发消极情绪的还有我们长久以来形成的五种不良认知模式\u003c/strong>\u003c/p>\u003cp>除了“下判断”和“找原因”之外，导致我们产生负面情绪的，还有长久以来形成的不良认知模式，这里要跟大家分享五种主要的不良认知模式。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>专横无理”的“应该”\u003c/strong>\u003c/p>\u003cp>我们认为事情或对方“应该”怎样，或者“必须”怎样。心理学家埃利斯把这种缺少宽容度的心态称为“苛求”，因为我们在心中要求某些事情必须发生或者必须不发生。但这种苛求往往是非常无理的，而且当别人没有按照我们认为“应该”的方式去做时，我们心头的怒火就会冒出来。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>杞人忧天”的想法\u003c/strong>\u003c/p>\u003cp>这也是一种常见的倾向，就是夸大事件的消极后果，尤其指我们把某些自己不喜欢的，不如意的事情看成是糟糕的、可怕的、灾难性的。如果我们带着这种想法去做事情，就会感到沮丧，从而不愿面对。从小小的争执，到不得不与自己厌恶的人在一起共事都可以让我们觉得像一场灾难--只要我们告诉自己：这是一场灾难。如果是严重的问题，由于我们夸大其消极后果并为此惶惶不可终日，就会更加痛苦。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>非黑即白”的思维\u003c/strong>\u003c/p>\u003cp>这是一种看待事物走极端的方式，认为事物要么是好的，要么是坏的，忽略了中间状态。你会把人或事评价为好的或坏的、正面的或负面的、成功的或失败的，并且没有认识到大多数情况既不是美妙绝伦的，也不是惨不忍睹的，而是出于一种中间状态。走极端的看法使我们的思维模式发生扭曲，更容易导致极端的情绪产生，而且让我们无法看到更好的解决问题的方法。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>以偏概全”的习惯\u003c/strong>\u003c/p>\u003cp>我们以有限的依据为基础，对自己和别人得出消极的结论。有时候，仅凭一次经历，我们就用“总是”“从来不”“每个人”这样的绝对的想法来思考。例如，“每当情况开始好转，就总会出乱子”“每次我试图与她沟通，都毫无用处”等。有了这种以偏概全的习惯，我们经常会陷入消极的负面情绪。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>\u003cstrong>责备他人”的倾向\u003c/strong>\u003c/p>\u003cp>当问题产生时，很多人倾向于归罪于对方的过失。责备别人的问题在于，只会产生痛苦和憎恨，却不能解决问题。实际上，责备对方不但妨碍了我们采取积极的行动来改变处境，而且很有可能破坏双方的关系。\u003c/p>","explains":"\u003cp>What\u003c/p>\u003cp>这一段，讲述的是消极情绪的根源--消极认知\u003c/p>\u003cp>消极认知包括两个大类，分别是“下判断、找原因”和“五大不良认知”\u003c/p>\u003cp>1、下判断、找原因\u003c/p>\u003cp>这是非常常见的不良认知，就像我刚刚跟大家分享的回家看见孩子在看电视的例子，我们脑子里就立刻下了一个判断：这小子不想好了！立马找了个原因：一定是不想做作业、贪玩！从而引发消极情绪，后果自然不是想要的~\u003c/p>\u003cp>2、五大不良\u003c/p>\u003cp>【给出更贴近实际的例子】\u003c/p>\u003cp>（1）专横无理，觉得人家“应该”如何如何\u003c/p>\u003cp>这种认知好像在男女关系里很常见，比如女生总觉得男生“应该”照顾我，吵架了“应该”他来哄我，没做到？！你不爱我！分手！\u003c/p>\u003cp>（2）杞人忧天，怕怕怕怕怕怕\u003c/p>\u003cp>这种认知我有体会，2-1拆完，我觉得效果不好，在面对2-2的准备时，我就有了这种认知，害怕讲解不完美、提问不精巧，我要是没过下次就该害怕了，再不过就丢人了，师父真是好可怜我耽误师父的江湖地位了···恩，这就很典型，不过我现在已经调整了自己的消极认知，等下也会给大家分享，不要太期待哦~\u003c/p>\u003cp>（3）非黑即白，要么这样要么那样，都不行？完了完了惨了\u003c/p>\u003cp>有了这种认知，往往感觉自己陷入了两难的境地。比如一家公司大裁员，王经理首席裁去了50%的人，结果活儿还是一样多，相当于他的工作量增加了一倍。压力啊！他就想：要不然就招新人，要不然就自己玩命儿干累死，可是前者公司不从，后者自己不甘。愁死个人咯！\u003c/p>\u003cp>（4）以偏概全，看见一根草，说是全宇宙\u003c/p>\u003cp>这种认知也蛮常见的。再比如我刚刚说的看见孩子看电视的例子，看见一次你就说人家贪玩，这难道不是以偏概全的认知么？~\u003c/p>\u003cp>（5）责备他人，都是你的问题！\u003c/p>\u003cp>这种认知在成人的世界里也很常见呀！比如，小周向另外一个部门收集材料，他发邮件给了小林，说是两天后提交。可是两天后催交无果，小周气死了，他觉得都怪小林，不配合自己让自己没有完成工作。\u003c/p>\u003cp>【异议预防】\u003c/p>\u003cp>我刚刚举了这二大类消极认知的具体案例，帮助大家理解认知的内容。从我刚刚举的例子中大家可以看到，两大类消极认知并不是完全独立的，常常相伴相随，五大不良也可能交叉在我们的认知中体现。作者这样的分类仅仅是为了统筹，让我们了解我们的消极认知都有哪些。\u003c/p>\u003cp>How【细化了原文的步骤】\u003c/p>\u003cp>为了发现自己的消极认知，分析自己的消极情绪的来源。遇到不良情绪时我们可以问自己三个问题（写出来）：\u003c/p>\u003col>\u003cli>\u003cp>我基于目前状况的认知是什么？\u003c/p>\u003c/li>\u003cli>\u003cp>我是不是急于“下判断”和“找原因”了？\u003c/p>\u003c/li>\u003cli>\u003cp>是不是有不良的认知模式在作祟？\u003c/p>\u003c/li>\u003c/ol>\u003cp>Why（指出一般做法-坏处例子-正面例子）\u003c/p>\u003cp>【强调不那么做的坏处】\u003c/p>\u003cp>一般情况下我们遇到了不好的情绪，往往就发泄出来了，比如生气--发火、委屈--哭，可是发泄后，你知道为什么会有这样的情绪么？下次你可以做哪些改进让自己拥有一个强健的心？\u003c/p>\u003cp>不，你不知道。如果没有依照3个问题分析自己的消极认知，往往就会模模糊糊，下次还会栽在同一个认知上。比如我小时候妈咪总是嫌我不好好学习，老生我气，有时候还会气得面瘫。我纵然调皮，可是如果这本书能出现得早一些，我妈咪能够学到发现自己的消极认知，就能改掉这个情境下的消极情绪了。\u003c/p>\u003cp>妈咪没有学到，我学到了，举个正面的栗子看看\u003c/p>\u003cp>2-1拆完后，我觉得不理想，觉得自己可能2-2不来噻，很害怕自己过不了。我的情绪是害怕。这是我的例子。\u003c/p>\u003cp>我问自己三个问题：\u003c/p>\u003col>\u003cli>\u003cp>我基于目前状况的认知是什么？\u003c/p>\u003c/li>\u003c/ol>\u003cp>我2-2可能过不了了\u003c/p>\u003col>\u003cli>\u003cp>我是不是急于“下判断”和“找原因”了？\u003c/p>\u003c/li>\u003c/ol>\u003cp>恩，还没发生呢！我着急下判断了！\u003c/p>\u003col>\u003cli>\u003cp>是不是有不良的认知模式在作祟？&nbsp;\u003c/p>\u003c/li>\u003c/ol>\u003cp>恩！我怕~~应该是犯了“杞人忧天”的认知了！\u003c/p>\u003cp>这样，我就可以定位自己的消极认知是犯了“下判断”和“杞人忧天”这两戒，我就可以对症下药，改掉我在这个情境下的消极认知啦！\u003c/p>\u003cp>适用边界\u003c/p>\u003cp>对于所有的消极情绪，大家都可以问自己这三个问题，并且定位自己的消极认知。\u003c/p>","interaction":"\u003cp>【A1】激活经验—显像提问（3分钟）\u003c/p>\u003cp>请认真听这些词汇，哪一个让你感觉熟悉--生气、懊恼、挫败、委屈、抑郁、紧张、愤怒、害怕···哪个词是你熟悉的，是你近期经历过的？请在便签纸上写下这个词。\u003c/p>\u003cp>然后，你最近一次感受到这种情绪，是什么时候，是什么事情？请想一想，在小组内分享。给大家2分钟的时间。2分钟后请1位小伙伴分享。\u003c/p>\u003cp>【A1+】催化应用（3分钟）\u003c/p>\u003cp>请大家进入刚刚你想到的情绪和事情，假设你回到了过去，你感受到了那种消极情绪后，怎么问自己三个问题，找出自己的消极认知呢？\u003c/p>\u003cp>请想一想，在小组内分享。给大家2分钟时间。2分钟后请1位小伙伴分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":4215,"quote":"\u003cp>\u003cstrong>调整认知的两个重点\u003c/strong>\u003c/p>\u003cp>利用CCEA模型，把消极的情绪调整为积极的情绪，就需要将消极的认知调整为积极的认知，进而起到调整情绪的作用。调整认知的重点在于两个方面：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 以“积极的目标”为导向，不要陷入急于“下判断”和“找原因”中。当我们遇到问题时，不能急于“下判断”和“找原因”，这样会使自己陷入消极的情绪，我们应该重新思考我们的目的是什么，以目的为导向，不让自己陷入消极的情绪中。\u003c/p>\u003cp>（2）&nbsp;&nbsp; 调整五种“不良认知模式”。前面我们特别分析过有五种不良的认知模式导致了负面的情绪，而且这些负面的情绪往往又带来消极的结果，所以我们需要调整这五种不良的认知模式，进而调整我们的情绪：\u003c/p>\u003cp>l&nbsp; 由“专横无理”的“应该”到“换位思考”\u003c/p>\u003cp>l&nbsp; 由“杞人忧天”的想法到“积极解决”\u003c/p>\u003cp>l&nbsp; 由“非黑即白”的思维到“跳出局限”\u003c/p>\u003cp>l&nbsp; 由“以偏概全”的习惯到“了解情况”\u003c/p>\u003cp>l&nbsp; 由“责备他人”的倾向到“反思自己”\u003c/p>\u003cp>\u003cstrong>调整情绪的话术如下：\u003c/strong>\u003c/p>\u003cp>句式：“我不能偏离我的目标（以目标为导向），我不陷入······（下判断，找原因和五种不良的认知模式），所以我要······（明确目标和五种不良认知模式对应的积极方面）”\u003c/p>","explains":"\u003cp>大家都非常聪明，很快get到自己的消极认知，我感觉灰常自豪！~找到病症了，就可以对症下药了。药呢？~就在这个拆页中！~\u003c/p>\u003cp>给大家1分钟的时间阅读。\u003c/p>\u003cp>记得抛媚眼哦~\u003c/p>\u003cp>哈哈，拆页很短又很干，木事儿，听我娓娓道来！~\u003c/p>\u003cp>What&amp;Why（包括一般做法-坏处-正面例子）\u003c/p>\u003cp>【强调不那么做的坏处】\u003c/p>\u003cp>这一段是在教我们调整认知成为积极的状态。包括两大类消极认知的对策和调整情绪的话术。\u003c/p>\u003cp>首先我们来看，应对两大难题，n个对策！请看大屏幕！~\u003c/p>\u003cp>1、下判断、找原因--积极的目标导向\u003c/p>\u003cp>意识到自己是在“下判断、找原因”，就得立马提醒自己积极的目标导向。看到孩子看电视，妈咪破口大骂，是会摧毁小朋友的幼小心灵，疏远母子关系的。如果麻麻提醒自己“我的目标是教导孩子天天向上，而不是生气发火的”可能妈妈就会好好说话，而不是打骂。这样，母子关系岂不融洽，孩子岂不向上？~\u003c/p>\u003cp>2、五大不良\u003c/p>\u003cp>（1）专横无理--换位思考\u003c/p>\u003cp>谈恋爱的女生总是蛮横无理地要求“你应该来哄我，不来？你不爱我，分手！”，这俩人还能好么，女的恐怕要灭绝师太了。如果定位到自己的消极认知--专横无理，然后对照相应的策略改变，换位思考，想想男生是不是有苦衷有理由？电话一打，一和好，甜甜蜜蜜嘛。\u003c/p>\u003cp>（2）杞人忧天--积极解决\u003c/p>\u003cp>我如果一直心惊胆战，觉得自己过不了2-2，恶化了之后可能觉得我走不过全世界。但是意识到自己在“杞人忧天”，而这一切都没有发生，仍有机会转变，我就积极解决：我给自己放了小假，把红宝书前后都读了，到网上看别人的实录，写完自己的准备表给师父师姐师兄师弟师妹们修改。我的认知改了，心态情绪变了，你看我这结果也好了吧！\u003c/p>\u003cp>（3）非黑即白--跳出局限\u003c/p>\u003cp>如果被裁员的王经里，总是被局限在一个方框里，觉得除了招新人就是自己累死，他估计会压力特别大甚至影响健康。但意识到自己的消极情绪--非黑即白时，王经理可以跳出局限，如跟自己的直属上司沟通，看看是否可以请上司画出业务重点、利用上司的资源拓展业务，跳出局限，事情解决了，也不至于愁死啊！~\u003c/p>\u003cp>（4）以偏概全--了解情况\u003c/p>\u003cp>还是看电视的孩子（大家最近看到孩子看电视会不会想起我···）看见一次你就说人家贪玩，孩子肯定是各种委屈，还会滋生不自信和不信任他人的种子。如果你意识到自己在以偏概全，就可以问问孩子，积极了解情况，为什么看电视啊，作业写完了么，遇到什么问题了？~这样，在孩子乖乖学习的同事，你是不是离宝宝更进一步了呢？\u003c/p>\u003cp>（5）责备他人--反思自己\u003c/p>\u003cp>小周向跨部门的小林要资料，小林没给。小周一味地责备他人，势必自己的人际关系出错。如果认识到自己在责备他人，小周能反思自己：我这个行政流程对么，是不是要跟小林的上司打个招呼？是不是要走oa？我发了邮件咋不打电话呢？这样同事关系岂不美哉？\u003c/p>\u003cp>这样，利用对应的对策解决相应的认知，对症下药，条理清晰。可以把当下的消极情绪逆转，将事态向好的方向发展。\u003c/p>\u003cp>How\u003c/p>\u003cp>我们仍旧有一套话术，促使我们应用到以上的学习，催化积极情绪的产生，请看大屏幕：\u003c/p>\u003cp>我不能偏离我的目标（以目标为导向），我不陷入······（下判断，找原因和五种不良的认知模式），所以我要······（明确目标和五种不良认知模式对应的积极方面）。\u003c/p>\u003cp>【更贴近实际的例子】\u003c/p>\u003cp>以我拆书做栗子吧！当我2-1不理想，害怕2-2时，我要这么告诉自己：我不能偏离我掌握拆书能力的目标，我不陷入杞人忧天和下判断，所以我要冷静下来，积极地寻找可以增强自己拆书能力的方法，而不聚焦于2-2的结果。\u003c/p>\u003cp>【异议预防】\u003c/p>\u003cp>也许话术比较麻烦，但是是一种自我引导的方法，非常适合开始训练自己积极情绪时使用。\u003c/p>","interaction":"\u003cp>【A3】促动参与现场演练（16分钟）\u003c/p>\u003cp>刚刚我们学习了消极认知的对应方法，并且用话术自我引导，现在一起做一个演练吧。\u003c/p>\u003cp>请大家认真听一下要演练的场景：\u003c/p>\u003cp>职员麦克是一位销售，他所负责的片区在第三季度下跌30%。大区经理汤姆非常气愤，因为这直接关系到了他的晋升。汤姆质问麦克原因，而麦克认为这并不是自己所能控制的。\u003c/p>\u003cp>请小组内一人扮演麦克，一人扮演上司汤姆，可简单演绎两人的对话。然后请记住自己当下的消极情绪，并用话术演练，使认知和情绪转而积极。请注意，演绎只是为了进入消极情绪，重点是用话术进行演练。小组还有一人扮演观察员的角色，观察二人的演绎，确保重点在话术的应用上。\u003c/p>\u003cp>给大家6分钟的时间进行演练，然后我请几个小组为大家演绎。\u003c/p>\u003cp>【A2】催化应用（13分钟）\u003c/p>\u003cp>刚刚的现场应用大家做得很棒！但我想你并不是麦克或者汤姆，那么今天学到的话术怎么应用于自己的生活工作中呢？\u003c/p>\u003cp>与另一半相处、教育小孩、领导下属···你在生活和工作中会涉及哪个场景？\u003c/p>\u003cp>请大家想到一个具体的场景，如果在场景中触发了你的消极情绪，可能产生了什么消极认知，如何利用话术改善认知？\u003c/p>\u003cp>请在小组内分享你的场景和应用，给大家5分钟时间。然后我请几个小组为大家分享。\u003c/p>\u003cp>【总结】（1分钟）\u003c/p>\u003cp>大家的例子都很贴切。我甚欣慰~大家刚刚已经做好计划咯，当遇到难题情绪负向时，先通过问自己3个问题，寻找自己的消极认知，再通过话术，套用针对消极认知的策略，转变成为积极认知，促进积极情绪，达成积极结果。不要忘记持续使用哦~谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1482302296000,"updated_at":1482302296000,"ria":true},{"id":1451,"topic":"如何迅速解决问题","learn_goal":"澄清问题本质SEE公式的使用","remark":"    这本书是一本图文并茂，技巧方法特别清晰的书籍，有很多研究情绪控制的书籍，并且情绪这个东西是看不到，摸不到的，但是这本书就把复杂摸不清的情绪这个东西系统化的讲的很透彻，分析清晰明了简单易懂。\r\n    里面很多实用的解决情绪问题的公式比如4A模型，ACT模型等。我亲自体验过，对我来说起到了作用，并且也帮我解决了一些棘手的人际关系问题。对照使用这些技巧公式，那些让你头疼的情绪问题将会很好解决了。\r\n    书中有一句口号：先解决心情，在解决事情！\r\n","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"朱莹","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"各位亲们大家晚上好，我是朱莹，今天我给大家带来我的2-1的拆解，期望今天的分享也期望自己的讲解逻辑能够清晰明了，并且给大家带来收获哦。。 \r\n那么今天我为大家带来的片段来自由机械出版社出版的《《积极达成》 这本书，他的作者是王明伟\r\n它是属于控制情绪，提高自我情绪控制力的情商类型书籍，上下两篇的内容主要是：先处理情绪，在处理事情，这也是这本书独特的一个口号。\r\n这是我们公司董事长买了发给我们的书籍哦。\r\n 这本书是一本图文并茂，技巧方法特别清晰的书籍，有很多研究情绪控制的书籍，并且情绪这个东西是看不到，摸不到的，但是这本书就把复杂摸不清的情绪这个东西系统化的讲的很透彻，分析清晰明了简单易懂。\r\n 里面很多实用的解决情绪问题的公式比如4A模型，ACT模型等。我亲自体验过，对我来说起到了作用，并且也帮我解决了一些棘手的人际关系问题。对照使用这些技巧公式，那些让你头疼的情绪问题将会很好解决了。\r\n 那么今天我给大家带来的片段主要是想让大家学会在碰到面临解决各种大小问题的时候，能够迅速的澄清问题本质是什么，真正需要解决的问题是什么给迅速的分析出来，从而有助于解决问题","ratings_count":0,"texts":[{"id":3960,"quote":null,"explains":"\u003cp>&nbsp; &nbsp; 这个模型的使用背景是：工作中或生活中一个问题出现了，你面临着如何去解决问题的困境。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;那么解决问题的前提和重要的一步是明白我们的处境，老话说：“谋定而后动”想要解决问题，那就先了解清楚问题是什么？\u003c/p>\u003cp>为了更好的 问题，我们需要收集到三个方面的关键信息：\u003c/p>\u003cp>\u003cstrong>现状：\u003c/strong>即搞清楚我们面临的现状是什么？\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>即定下来我们的目标是什么？\u003c/p>\u003cp>\u003cstrong>现有资源和制约条件：\u003c/strong>即弄清楚已有资源和制约条件是什么。也就是弄清楚我们有什么王牌在手上或者有什么短板。\u003c/p>\u003cp>根据定义，问题就是现状和目标之间的差距，并且为了解决问题，我们还需要了解已有资源和制约条件是什么。这样才能清晰的攻克看似一团糟的问题，立马将他捋的清清楚楚明明白白、\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>运用这模型的限制条件是：\u003c/strong>有明确的目标才行，假若目标不清晰，可以使用SMART原则来确定清晰目标。&nbsp;\u003c/p>\u003cp>下面与大家分享一个书中的案例：\u003c/p>\u003cp>&nbsp;&nbsp; 小王 身高160，但是体重达到了140斤，她现在就想减肥，但是目标不能太模糊，不然不能衡量，所以她标就是在今年12月份之前减肥到120斤，\u003c/p>\u003cp>那么把SEE信息匹配一下：\u003c/p>\u003cp>现状：体重140斤，爱吃肉，爱吃甜食，喝饮料，不爱运动。\u003c/p>\u003cp>目标：12月份之前减肥到120斤\u003c/p>\u003cp>现有资源条件：周末不上班休息，工作有一定的收入。制约条件，平时要上班，比较忙，下班之后就想睡觉。\u003c/p>\u003cp>经过这么一分析，问题就清晰了\u003c/p>\u003cp>\u003cstrong>基于目前现状\u003c/strong>（体重140斤，爱吃肉，爱吃甜食，喝饮料，不爱运动。\u003c/p>\u003cp>）\u003cstrong>如何在制约条件\u003c/strong>（平时要上班，比较忙，下班之后就想睡觉。）l\u003cstrong>利用现有资源\u003c/strong>（周末不上班休息，工作有一定的收入）达到（12月份之前减肥到120斤）\u003cstrong>目标。\u003c/strong>\u003c/p>\u003cp>这个see公式的功能就是将复杂的事情清晰化。\u003c/p>\u003cp>面临问题之后，只有把问题从乱麻中如同剥丝抽茧的分析出来，才能利于下一步解决问题行动的实施。\u003c/p>","interaction":"\u003cp>与大家分享一下我运用这个公式的心得哈;\u003c/p>\u003cp>&nbsp;&nbsp; 9月底的时候，老大安排我一个任务，就是整理公司各个部门主要工作的工作流程。目的是规范各部门工作开展，并且有利于人才的轮岗，就是有固定的流程下人变动都不会有影响。\u003c/p>\u003cp>刚开始拿到这个任务，我是一头雾水的，只知道要做这个事情，但是具体该去怎么解决这个事情，怎样才叫流程，流程的标准是什么样？每个部门的工作职责不同，我怎么知道我整理的他们的工作流程就是对的呢？\u003c/p>\u003cp>所以一直拖着没有动手做。因为感觉无从下手。\u003c/p>\u003cp>到了10月初，我旅游回来，老大问我流程的工作进行的怎么样？我兢兢战战的说，还没有弄好，。于是老大把我一顿骂，说我：休假出去玩，事情都没有做完计划拖到什么时候完成，我说10月30号之前。\u003c/p>\u003cp>然后我按照这个SEE步奏，静下心来把这个问题好好的分析了一下：\u003c/p>\u003cp>\u003cstrong>S: \u003c/strong>\u003cstrong>现状：\u003c/strong>老大安排的这个任务已经被拖延了一个月且没有动工\u003c/p>\u003cp>\u003cstrong>E\u003c/strong>\u003cstrong>：目标：\u003c/strong>2015年10月30号之前，完成公司7个部门重点工作流程的梳理并编辑出来的工作。\u003c/p>\u003cp>\u003cstrong>E\u003c/strong>\u003cstrong>：现有资源：\u003c/strong>1、各个部门负责人经过沟通愿意协助我来完成，他们给我一些资料。 2、百度和其他一些专业网站上搜索了解流程的定义和标准\u003c/p>\u003cp>&nbsp; 3、向身边的人资管理的专业人士请教，比如我就给真姐打过电话咨询流程的和定义和标准的问题。\u003c/p>\u003cp>&nbsp; 4、可以向经营部主管学习请教word使用技巧，因为他很精通并且人很好。\u003c/p>\u003cp>&nbsp;\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>制约条件：\u003c/strong>1、自己的WORD使用并不精湛，制作成文档的流程，需要熟练使用WORD来编辑流程图。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2、我不知道流程的标准是什么，不知道怎样制作流程，每个部门的工作哪些是重点工作，哪些是可以制作成流程的？\u003c/p>\u003cp>那么经过这样的一分析，我自己思路清晰明了，原来这个看似很头疼的问题就是这样的：老大安排的这个任务已经被拖延了一个月且没有动工的基础上，如何在不知道流程是什么、WORD使用并不精湛的制约条件下，利用各部门负责人的协助，专业网站资料查询，身边专业人士请教，以及经营部主管的WORD的请教这些条件下，达成2015年10月30号之前，完成公司7个部门重点工作流程的梳理并编辑出来的工作。这么一分析，我就认为解决这问题是有可能性的。是应该能够试试的。\u003c/p>\u003cp>那么这是我自己运用SEE信息解决这个问题的基本思路。\u003c/p>\u003cp>&nbsp;那么相信经过我这样一讲解，大家应该都比较清楚这个SEE是啥并且应该能理解如何使用了对吗？\u003c/p>\u003cp>请问大家，最近一周，或者一个月之内，有没有一件需要花费比较大精力去处理的事情呢？这件事情可以是工作中的，也可以是生活中的哦。\u003c/p>\u003cp>有的话，请大家写下来。\u003c/p>\u003cp>好的，写完了之后，请问大家，当你面临这个问题的时候，如果运用这个SEE法则，你会如何运用呢？\u003c/p>\u003cp>比如你最近遇到一个很头疼的问题，就是在一家公司呆了三年了，老板一直没有给你加过工资。那么我们如何运动这个SEE法则把这个问题给清晰化一些呢？\u003c/p>\u003cp>现场有一位小伙伴一直想拿驾照，但是因为种种原因，一直没有拿到驾照。现在他面临的问题经过这样的一个SEE分析，其实就是这样的：\u003c/p>\u003cp>现状：已经报名，很久没有去学\u003c/p>\u003cp>目标：2016年3月份之前拿到驾照。\u003c/p>\u003cp>现有资源和制约条件：每天周一到周五上班没有时间，\u003c/p>\u003cp>周六周日抽一天时间练车，并且由于想上下班方便，接送小孩更加方便的目的，更加的想拿到驾照。\u003c/p>\u003cp>&nbsp;经过这样一分析，这位小伙伴一直拿不到驾照的问题非常清晰，接下来也非常的有计划的去行动了。\u003c/p>\u003cp>&nbsp;\u003cstrong>结束语：碰到问题，能够迅速的澄清问题本质是什么，真正需要解决的问题是什么给迅速的分析出来很重要哦，咱们一起使用SEE工具吧！\u003c/strong>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480218394000,"updated_at":1480218394000},{"id":1444,"topic":"执行工作的时候，分工和跟进的wwwt工具","learn_goal":"碰到执行层面工作使用wwwt工具","remark":"当我们找到了解决问题的方案之后，为了避免出现烂尾工程的局面，在执行方案的时候，必须要进行明确的分工，做什么，和什么时间完成或沟通，并安排相关的跟进计划，这样可以确保工作任务在可空中，同时增强了大家的责任感，这个工具也是一个闭环管理，对以后的持续改进打下很好的基础。\r\n这个WWWT工具，\r\nW  WHO  谁需要参与\r\nW  What   该做什么\r\nW  when   什么时候完成沟或沟通\r\nT  track   跟进\r\n","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"朱莹","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我是朱莹哦，我是一级拆书家，今天我给大家带来的是我的2-2的拆解，希望今天打怪顺利升级成功哦。今天我要带来的片段源自《积极达成》这本书，这本书主要是教我们如何扭转消极局面，达成积极的结果，他的口号是处好情绪，在处理问题，书中上部分详细的讲解了一些处理情绪的技巧比如4A法则。下部分就是讲解如何清晰的处理问题的相关方法技巧。\r\n F特征：回到说积极达成这本书哈，这本书是我们老板买给我大家的，老板在众多书籍中选了这本，是因为本书中提供了大量能精准、可行的方法步奏的工具来解决情绪问题、最终圆满的处理好问题。\r\nA优势：情绪方面的书籍很多，包括如何处理问题百人百见解。但是这本书能够系统化的深入浅出的，整理出来系统行动公式，并且这些行动公式非常易于使用。一学即用。\r\nB益处：1、做人资管理工作的，平常或多或少都会遇到一些矛盾的场面，这些方法和技巧让我的工作开展更加顺畅了，并且当我一展莫愁的时候，翻开这本书，都能找到一些解决之道！\r\n2、当工作中遇到问题，找出了解决方案之后，执行这个方案也是一个非常重要的过程，那么我这个片段的主题就是为了达成我们所要解决问题的结果，通过学习并应用这个技巧","ratings_count":0,"texts":[{"id":3959,"quote":null,"explains":"\u003cp>当我们找到了解决问题的方案之后，为了避免出现烂尾工程的局面，在执行方案的时候，必须要进行明确的分工，做什么，和什么时间完成或沟通，并安排相关的跟进计划，这样可以确保工作任务在可空中，同时增强了大家的责任感，这个工具也是一个闭环管理，对以后的持续改进打下很好的基础。\u003c/p>\u003cp>这个WWWT工具，\u003c/p>\u003cp>W&nbsp; WHO&nbsp; 谁需要参与\u003c/p>\u003cp>W&nbsp; What&nbsp;&nbsp; 该做什么\u003c/p>\u003cp>W&nbsp; when&nbsp;&nbsp; 什么时候完成沟或沟通\u003c/p>\u003cp>T&nbsp; track&nbsp;&nbsp; 跟进\u003c/p>\u003cp>我与大家分享一个书中的案例，雷海是一家IT行业的世界500强外企做区域销售总监，天津分公司下属叫范嘉，他们遇到了一个问题，就是开拓天津市场进度慢，业绩不达标。进过他们运用PRO模型解决问题了之后，他们制定出来一个方案是：\u003c/p>\u003cp>&nbsp; 重点扶持忠诚度高，愿意投入资源的代理商两三家，先把市场做起来，在吸引其他代理商。\u003c/p>\u003cp>进行的分工是：\u003c/p>\u003cp>WHO&nbsp; 谁需要参与&nbsp; 范嘉\u003c/p>\u003cp>What&nbsp;&nbsp; 该做什么&nbsp;&nbsp; 选出三家忠诚度高的代理商，谈好合作方式，重点支持他们拓展市场\u003c/p>\u003cp>&nbsp;when&nbsp;&nbsp; 什么时候完成沟或沟通&nbsp; 本周内完成代理商候选名单，下周内完成代理商洽谈事项\u003c/p>\u003cp>track&nbsp;&nbsp; 跟进&nbsp; 每周一与代理商一起开例会时，进行跟踪代理商的完成进度。\u003c/p>\u003cp>&nbsp;&nbsp; 通过这样一分析，雷海帮助范嘉梳理清楚了执行步奏，这样也能更加有利于达成销售目标。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>这个工具的适用条件是：已经制定出来了解决方案了。只剩下执行的步奏了。\u003c/strong>\u003c/p>\u003cp>前不久，公司老大要求我组织一场全体员工的岗位角色模拟培训，\u003c/p>\u003cp>后来经过和部门同事的沟通和讨论，列出来一个行动方案。首先与每位员工沟通工作中的主要职责和想体现出来的一个点，然后利用分组讨论和抽签的方式，组织开展好这场培训。\u003c/p>\u003cp>&nbsp; 其实一开始想到这些工作，我就头疼，这个事情是需要做很多细节准备工作的，所以几天过去了，当领导问起我培训准备怎么样的时候，我回答不上来我准备怎么样，因为我们在准备培训资料，但是工作结果和进度不明显。&nbsp;\u003c/p>\u003cp>如何处理这种混乱没有效率的工作局面呢？我想到了WWW工具，当时我就做出分工如下：&nbsp;\u003c/p>\u003cp>W&nbsp; WHO&nbsp; 谁需要参与&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 同事A\u003c/p>\u003cp>W&nbsp; What&nbsp;&nbsp; 该做什么&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 负责与同事沟通谈话，整理出来培训需要的资料素材和场景，并且告诉他完成的标准和目标是什么。\u003c/p>\u003cp>W &nbsp;when&nbsp;&nbsp; 什么时候完成沟或沟通&nbsp;&nbsp; 9月11号完成\u003c/p>\u003cp>T&nbsp; track&nbsp;&nbsp; 跟进&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 每天下班前跟进一下进度。\u003c/p>\u003cp>W&nbsp; WHO&nbsp; 谁需要参与&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 同事B\u003c/p>\u003cp>W&nbsp; What&nbsp;&nbsp; 该做什么&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 设计出来培训过程中的细节，比如如何操作模拟培训，带入游戏的形式，让大家在游戏的同时完成这个情景模拟培训。并且告诉他完成的标准和目标是什么。\u003c/p>\u003cp>W&nbsp; when&nbsp;&nbsp; 什么时候完成沟或沟通&nbsp;&nbsp;&nbsp; 9月11号之前完成\u003c/p>\u003cp>T&nbsp; track&nbsp;&nbsp; 跟进&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;每天下班前跟进一下进度。&nbsp;&nbsp;\u003c/p>\u003cp>经过这样一分工，明确职责和义务时间，也不会出现分工不清晰出现相互推诿的局面了，我也能清晰的掌握工作进度，领导再问我准备怎么样，我能清晰的回答，我们已经做到哪个阶段了，我也只需要对着这个分工表来跟进，自然而然，这个工作就会有一个结果出来。\u003c/p>","interaction":"\u003cp>&nbsp;经过我这样的讲解，不知道大家是否清晰的了解了这个工具了呢？请问大家能够运用起来这个工具吗？\u003c/p>\u003cp>温馨提示哦：在用这个工具的时候，有一个前提，就是问题已经招到了解决方案了。剩下的是分工问题了。\u003c/p>\u003cp>&nbsp; 下面，我们一起来分组讨论一下，运用一下这个技巧好么？\u003c/p>\u003cp>大家工作中或者生活中有没有遇到一项系统化的难以解决的任务或问题呢？你自己能够想到什么好的解决方案？&nbsp;\u003c/p>\u003cp>\u003cstrong>请大家回想下，在最近\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>个月中，有某项相对复杂的工作，已经有了行动方案，但没有实施的？\u003c/strong>\u003c/p>\u003cp>请大家先写下来好吗？\u003c/p>\u003cp>&nbsp;&nbsp; 写下来之后，我们来进行分组，请组内成员都分别复述一下自己的问题，和解决方案。然后组内成员一起推选出一个最有代表性的问题和解决方案。&nbsp; 然后请利用这个步奏，来帮她进行分工，帮助他最终达到结果好吗？\u003c/p>\u003cp>请各位小组一一进行分享好么？\u003c/p>\u003cp>\u003cstrong>现场严劼的案例分享：\u003c/strong>\u003c/p>\u003cp>在2015年周年庆之前通过3-3\u003c/p>\u003cp>W&nbsp; WHO&nbsp; 谁需要参与&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 严劼&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>W&nbsp; What&nbsp;&nbsp; 该做什么&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在周年庆10.23号之前通过3-3&nbsp; \u003c/p>\u003cp>W&nbsp; when&nbsp;&nbsp; 什么时候完成沟或沟通&nbsp;&nbsp; &nbsp;9.9号才通过2-3，所以需要在9.16、9.23、10.14、10.21号，每次必须一次通过拆书。.\u003c/p>\u003cp>T&nbsp; track&nbsp;&nbsp; 跟进&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 师傅和各位拆书家们的跟进&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>亲们，想要结果吗？\u003c/p>\u003cp>&nbsp; 亲们，想要有执行力吗？\u003c/p>\u003cp>&nbsp;那就使用WWWT这个强大的工具吧。\u003c/p>\u003cp>只需要对方案进行明确分工并且跟进，执行力也会到位，结果就会出来，也能真正的解决问题哦。那么我今天的分享就到此结束了，也感谢大家的支持哦。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480167922000,"updated_at":1480167999000},{"id":1140,"topic":"通过调节认知来调节情绪","learn_goal":"识别不良情绪，及时稳定情绪","remark":"在生活工作中，我们可能经常遇到情绪不良的时刻，在愤怒、委屈等等消极情绪下，我们可能无法理性思考、做出合适的行为或决定。这时，处理情绪就尤为重要。《积极达成》这本书提出了一个理论：我们对情景做出的反应流程是--由情景触发认知、认知触发情绪、情绪决定我们的行动。由此，可以通过调节认知来调节情绪。针对调节认知，我们可以通过“质疑认知”“谨记积极的目标”两个行为来。具体做法应该是，质疑--产生认知时，反问自己“是不是我太快下结论了？”“是不是有其他原因？”；积极的目标导向--重新思考我们的真正目的，反复温习。","level":"TF1-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"小鹿","city":"苏州"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"我是小鹿，我的三个标签是“言控”“吃货”“进击的金牛”\r\n拆书是一种性价比超高的读书和应用方法。拆书的目的是解决既定问题、提升自身能力。它与自己在家里抱着书看有啥区别呢？我们自己在家里看书的时候，可能有这种情景“恩这个地方说的好！画下来画下来！”而拆书法提供了一个科学的标准流程，给你压力和动力，让你不得不从书本中关联自己，联想以前的经验和以后的应用计划。标准流程是RIA，R是Read，先阅读，I是Interpretation，以自己为中心深化理解，A是appropriation，应用，其中，A1是关联自己的经验，A2是根据学习到的内容制定计划。\r\n拆书帮就是拆书法学习爱好者社群，帮主是拆书法的创始人赵周先生，各地的社群叫做拆书帮分舵，这是一个公益性的组织，加入组织可以帮助拆书爱好者成为拆书家。\r\n今天的拆页选自《积极达成--处理好情绪，再处理问题》，宗旨就是在处理问题前先处理好自己情绪。积极达成的步骤是先处理好自己的情绪，再以合作的态度处理好别人的情绪，最终处理问题。针对每个步骤，书中有理论基础、实操步骤、大量的案例支持，是一本实用的工具书。","ratings_count":0,"texts":[{"id":3360,"quote":null,"explains":"\u003cp>这部分的目的是教我们通过调整认知来调整情绪。文中的两条建议都是为了帮助我们调整认知。\u003c/p>\u003cp>为什么我们要调整认知、调整情绪呢？在生活工作中，我们可能经常能碰到情绪不佳导致自己无法处理问题的情况，愤怒、不满、委屈等等负面情绪可能降低自己的判断力，使我们背离目的。这时情绪的调整是至关重要的。\u003c/p>\u003cp>而根据作者的观念（流程图），我们对情景做出的反应流程是：由情景触发认知、认知触发情绪、情绪决定我们的行动。比如，在公司项目中，同事未能及时提交阶段结果，你可能认为他没有责任心、没有团队荣誉感等，进而感到愤怒，可能会导致两人关系紧张、而项目也不能良好地进行下去。在这里，同事未能及时提交结果是情景，我的认知是他没有责任心--这同时是一种“下判断”和“找原因”，我的情绪就变成了愤怒，我的行动可能是责备、奚落等等，最终造成关系紧张、项目停顿等结果。\u003c/p>\u003cp>基于这样的理论，作者认为控制情绪应该从控制认知下手，两条建议分别是“质疑我们的下判断和找原因”“谨记原则：达成积极的目标”。\u003c/p>\u003cp>具体做法应该是，质疑--产生认知时，反问自己“是不是我太快下结论了？”“是不是有其他原因？”；积极的目标导向--重新思考我们的真正目的，反复温习。\u003c/p>","interaction":"\u003cp>A1激活经验\u003c/p>\u003cp>我认为自己是情绪先于逻辑的，并且急需改变，所以才会买来这本书学习。\u003c/p>\u003cp>我是做科技园管理的工作，工作中很多时间要和政府部门打交道，如向政府部门汇报阶段进展、对接政府领导指示等等。部门多不胜举，我有时需要和5个以上的接口人打交道，而这五个人都是临时发给我一张表格或一个文件，让我一个小时内发回给到他！有些表格逻辑混乱，我再向接口人询问时，他们说不归他们管，他们只负责传递！久而久之，我认为他们没有责任心、吃白饭···对待他们的态度很消极，导致现在看到qq抖我就会心情烦躁，置之不理，甚至直接关掉qq。\u003c/p>\u003cp>在这里，情景是与接口人对接信息，我的认知是接口人不明事理、没有责任心、吃白饭···我的情绪是消极、生气、烦躁，我的行动是置之不理甚至关掉qq。\u003c/p>\u003cp>A2催化应用\u003c/p>\u003cp>根据“通过调整认知来调整情绪”的原则和具体做法，下次在与接口人打交道出现逻辑混乱、信息不全、时间紧迫等障碍时，我应该这样调整认知：\u003c/p>\u003cp>1、质疑--“是不是我太快下结论了？”“是不是有其他原因？”--这次和上次一样吗？真的是他们没有责任心吗？是不是体制决定了就是这样？他们也没有办法提前通知我？他们也是刚刚拿到文件？整个传递链条那么长，他们是不是真的不了解表格的逻辑？\u003c/p>\u003cp>通过这样的质疑， 我的情绪会缓和一些，考虑得也会多了一些。\u003c/p>\u003cp>2、积极的目标导向--重新思考我的真正目的。我的目的其实是为了向上呈现科技园的美好形象，准确执行上级的重大决定，与直接上级打好关系。\u003c/p>\u003cp>通过积极的目标导向，我清晰了自己的目的，其中有与我之前的情绪冲突的地方--我应该与他们打好关系，而之前完全是负面关系，由此知道了自己的对错；另外，我的目的是执行上级的重大决定，对于同时传来的表格，我会优先处理重大决定的表格，确定了对接的优先级。\u003c/p>\u003cp>接下来一周内，将会关注自己的不良情绪，当自己情绪消极时，提醒自己“质疑下结论和找原因”思考实际目标，目标是做到遇挫时情绪稳定。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477020596000,"updated_at":1477363851000}]};